window.WB_BOOK=window.WB_BOOK||{};window.WB_BOOK["week05"]={"id":"week05","n":5,"section":"B","label":"","title":"Heat, Temperature & Thermal Measurements","titleText":"Heat, Temperature & Thermal Measurements","subtitle":"What heat really is, how we measure temperature, and how much energy it takes to warm, melt and boil things","intro":"This week starts Section B. You will learn the difference between heat and temperature, why scientists gave up the idea of heat as a fluid called caloric, how thermometers are designed, how the kinetic theory explains solids, liquids and gases, why things expand when heated, and how to calculate the energy needed to warm ⟪(E=mc\\Delta \\theta )⟫, melt or boil ⟪(E=ml)a⟫ substance. The two formulas ⟪E=mc\\Delta \\theta⟫ and ⟪E=ml⟫ appear on almost every Paper 02, often worth 6–10 marks together, and cooling curves are a favourite Paper 02 Question 1 graph. Learn these well and you will collect easy marks.","objectives":[{"code":"B1.1","text":"Distinguish between the caloric and kinetic theories of heat as they relate to the nature of heat"},{"code":"B1.2","text":"Explain the role of Joule in establishing the principle of conservation of energy (Joule's experiments)"},{"code":"B2.1","text":"Relate temperature to the direction of net thermal energy transfer"},{"code":"B2.2","text":"Identify physical properties which vary with temperature and may be used as the basis for measuring temperature (thermometric properties)"},{"code":"B2.3","text":"Relate the use of a thermometer to its design (liquid-in-glass laboratory, clinical and thermocouple thermometers: range, sensitivity, responsiveness)"},{"code":"B2.4","text":"Define the fixed points on the Celsius scale"},{"code":"B2.5","text":"Relate temperature to the kinetic energy of molecules"},{"code":"B2.6","text":"Distinguish among solids, liquids and gases"},{"code":"B2.7","text":"Use the kinetic theory to explain the macroscopic properties of solids, liquids and gases"},{"code":"B2.8","text":"Discuss the effects and applications of thermal expansion (bimetallic strip, gaps in railway lines, the anomalous expansion of water)"},{"code":"B3.1","text":"Distinguish between heat capacity and specific heat capacity"},{"code":"B3.2","text":"Perform calculations involving ⟪E_{H}=mc\\Delta \\theta⟫"},{"code":"B3.3","text":"Determine the specific heat capacity of metals and liquids using the method of mixtures and the electrical method"},{"code":"B3.4","text":"Demonstrate that the temperature of a substance remains constant during a change of phase (cooling curve)"},{"code":"B3.5","text":"Perform calculations involving ⟪E_{H}=ml⟫"},{"code":"B3.6","text":"Determine the specific latent heat of fusion and of vaporisation"},{"code":"B3.7","text":"Distinguish between evaporation and boiling"}],"formulaCard":[{"tex":"E_{H}=mc\\Delta \\theta","meaning":"Heat to change temperature (no change of state); ⟪\\Delta \\theta =\\theta _{\\text{final}}-\\theta _{\\text{initial}}⟫","units":"J (m in kg, c in J kg^−1^ °C^−1^, Δθ in °C or K)"},{"tex":"C=mc=E\\div \\Delta \\theta","meaning":"Heat capacity of a whole object","units":"J °C^−1^ (J K^−1^)"},{"tex":"E_{H}=ml","meaning":"Heat to change state (melt or boil) at constant temperature","units":"J (l in J kg^−1^)"},{"tex":"E=Pt=VIt","meaning":"Energy supplied by an electric heater","units":"J (P in W, V in V, I in A, t in s)"},{"text":"heat lost by hot body = heat gained by cold body","meaning":"Method of mixtures (conservation of energy)","units":"—"},{"tex":"c=VIt\\div (m\\Delta \\theta )","meaning":"Electrical method for specific heat capacity","units":"J kg^−1^ °C^−1^"},{"tex":"l_{f}=E\\div (m_{\\text{exp}}-m_{\\text{control}});\\quad l_{v}=Pt\\div (m_{1}-m_{2})","meaning":"Latent heat experiments","units":"J kg^−1^"},{"tex":"\\theta =(X_{\\theta}-X_{0})\\div (X_{100}-X_{0})\\times 100","meaning":"Temperature from a thermometric property X (length, resistance …)","units":"°C"},{"tex":"E_{p}=mgh\\ (\\text{work done in Joule's experiment})","meaning":"PE lost by falling masses → heat","units":"J"},{"text":"Key values","meaning":"⟪c_{\\text{water}}=4200⟫; ⟪c_{\\text{ice}}=2100\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫; l~f~(ice) ⟪=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫; l~v~(water) ⟪=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫; ice point 0 °C; steam point 100 °C; water densest at 4 °C; body temperature 37 °C","units":"—"}],"glossary":[{"term":"Caloric theory","def":"The old idea that heat is an invisible, weightless fluid (caloric) that flows from hot to cold bodies."},{"term":"Kinetic theory","def":"Matter is made of particles in constant random motion; heat is the energy of this motion."},{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Thermal equilibrium","def":"The state when two bodies in contact are at the same temperature, so there is no net heat flow."},{"term":"Thermometric property","def":"A physical property that varies continuously and measurably with temperature."},{"term":"Sensitivity","def":"How large a change in reading a thermometer gives for a 1 °C change in temperature."},{"term":"Responsiveness","def":"How quickly a thermometer reacts to a change in temperature."},{"term":"Range","def":"The lowest to highest temperature a thermometer can measure."},{"term":"Fixed point","def":"A reproducible temperature used to calibrate a scale: ice point 0 °C, steam point 100 °C."},{"term":"Brownian motion","def":"Random zig-zag motion of tiny visible particles caused by bombardment by invisible fluid molecules."},{"term":"Bimetallic strip","def":"Two different metals bonded together; it bends on heating because they expand by different amounts."},{"term":"Anomalous expansion of water","def":"Water expands when cooled from 4 °C to 0 °C, so it is densest at 4 °C."},{"term":"Heat capacity (C)","def":"Heat needed to raise the temperature of a whole body by 1 °C (J °C^−1^)."},{"term":"Specific heat capacity (c)","def":"Heat needed to raise the temperature of 1 kg of a substance by 1 °C (J kg^−1^ °C^−1^)."},{"term":"Latent heat","def":"Heat absorbed or released during a change of state at constant temperature."},{"term":"Specific latent heat of fusion","def":"Heat needed to change 1 kg of solid to liquid without a change in temperature (J kg^−1^)."},{"term":"Specific latent heat of vaporisation","def":"Heat needed to change 1 kg of liquid to vapour without a change in temperature (J kg^−1^)."},{"term":"Evaporation","def":"Change from liquid to vapour at the surface, at any temperature; causes cooling."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"lessons":[{"id":"week05.5.1","kind":"unit","unit":"5.1","title":"The Nature of Heat: Caloric Theory, Kinetic Theory and Joule","titleText":"The Nature of Heat: Caloric Theory, Kinetic Theory and Joule","goals":[{"code":"B1.1","text":"Distinguish between the caloric and kinetic theories of heat as they relate to the nature of heat"},{"code":"B1.2","text":"Explain the role of Joule in establishing the principle of conservation of energy (Joule's experiments)"}],"codes":["B1.1","B1.2"],"words":[{"term":"Caloric theory","def":"The old idea that heat is an invisible, weightless fluid (caloric) that flows from hot to cold bodies."},{"term":"Kinetic theory","def":"Matter is made of particles in constant random motion; heat is the energy of this motion."},{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."}],"learn":{"notes":[{"type":"h","text":"What is heat?"},{"type":"def","term":"Heat (thermal energy transfer)","text":"the energy that flows from a region of higher temperature to a region of lower temperature because of the temperature difference. Unit: joule (J)."},{"type":"p","text":"Today we know heat is a form of **energy**. But for about 100 years (1700s to the mid-1800s) most scientists believed heat was an invisible **fluid**. CSEC asks you to compare the two ideas."},{"type":"h","text":"The caloric theory (the OLD idea)"},{"type":"bullets","items":["Heat was an invisible, weightless **fluid called caloric**.","A hot body contained **more caloric** than a cold body.","Caloric **flowed** from hot bodies to cold bodies.","Caloric could **not be created or destroyed** — the total amount was fixed.","When things were rubbed or hammered, caloric was supposedly \"squeezed out\" of them."]},{"type":"h","text":"Why the caloric theory failed — Count Rumford (1798)"},{"type":"p","text":"Benjamin Thompson (Count Rumford) watched brass **cannon barrels being bored** (drilled) by horse-driven drills. He noticed:"},{"type":"bullets","items":["The metal and drill became so hot they could **boil water** — and kept producing heat for **as long as the boring continued**. Heat seemed to be **unlimited**, but caloric was supposed to be a fixed amount.","A **blunt** drill, which cut away very little metal, produced **even more** heat. If heat was caloric squeezed out of the metal shavings, less cutting should give less heat.","The metal chips weighed the **same** before and after — caloric had no detectable mass.","Rumford concluded that heat is produced by **motion (work done against friction)**, not released from a stored fluid."]},{"type":"h","text":"The kinetic theory of heat (the MODERN idea)"},{"type":"bullets","items":["All matter is made of tiny particles (atoms and molecules) that are **always moving**.","Heat is a form of **energy** — the energy of the motion of these particles.","Heating a body makes its particles move (vibrate) **faster**, so their kinetic energy increases.","Heat **can be produced** by doing work (e.g. friction) — mechanical energy is converted into thermal energy.","Energy is conserved: the work done equals the heat produced."]},{"type":"table","headers":["Caloric theory","Kinetic theory"],"rows":[["Heat is a weightless fluid (caloric)","Heat is a form of energy (energy of moving particles)"],["Hot body contains more caloric","Particles of a hot body have more kinetic energy"],["Caloric cannot be created or destroyed","Heat can be produced from work (e.g. friction); total ENERGY is conserved"],["Cannot explain unlimited heat from friction (Rumford)","Explains friction heating: work done → thermal energy"]]},{"type":"h","text":"James Prescott Joule (1818–1889)"},{"type":"p","text":"Joule, an English brewer and scientist, did careful experiments in the 1840s that proved heat is energy and that **a fixed amount of work always produces the same amount of heat**."},{"type":"img","src":"img/week05/joule_paddle","alt":"Figure 5.1 — Joule's paddle-wheel experiment: falling masses turn paddles that churn and warm the water","caption":"Figure 5.1 — Joule's paddle-wheel experiment: falling masses turn paddles that churn and warm the water","width":4.6,"w":1094,"h":728},{"type":"steps","items":["Masses fall through a measured height h, losing gravitational potential energy **mgh**.","As they fall, the strings turn a drum and spindle that spin **paddles** inside an insulated container of water.","Fixed vanes stop the water simply swirling round; the paddles **churn** the water, doing work against friction.","The water gets slightly warmer. A **very sensitive thermometer** measures the small temperature rise.","The masses are wound up and dropped many times (e.g. 20 times) to get a measurable temperature rise."]},{"type":"p","text":"**Joule's results and why they matter:**"},{"type":"bullets","items":["The **work done** (loss of PE of the masses) was always **proportional to** the heat produced in the water.","The same amount of work produced the same heat, whether by paddle wheels, electric currents or compressing gas — the **mechanical equivalent of heat** (about 4.2 J of work for every calorie of heat).","This showed mechanical energy is **converted** into thermal energy — none is lost. It helped establish the **principle of conservation of energy**.","The SI unit of energy, the **joule (J)**, is named in his honour."]},{"type":"def","term":"Principle of conservation of energy","text":"energy cannot be created or destroyed; it can only be changed from one form into another. The total energy of a closed system stays constant."},{"type":"tip","text":"A 3–4 mark \"role of Joule\" question wants: (1) falling masses turned paddles in water; (2) the work done (mgh) was measured and the temperature rise of the water was measured; (3) a fixed amount of work always gave the same amount of heat; (4) so heat is a form of energy and energy is conserved (conservation of energy)."},{"type":"warn","text":"Do not write that Joule \"invented energy\" or \"discovered heat\". He **showed that work and heat are equivalent forms of energy**, which supported the conservation of energy.","label":"COMMON MISTAKE"}],"examples":[{"id":"week05.5.1.e1","title":"A Joule-type experiment","question":"In a paddle-wheel experiment, two masses of 10 kg each fall through 2.0 m. They are wound up and dropped 20 times. The paddles churn 0.50 kg of water. Assuming all the work done becomes heat in the water, calculate (a) the total work done and (b) the temperature rise of the water. (⟪c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫, ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫)","steps":[{"label":"Formula (one drop)","text":"⟪E_{p}=mgh⟫"},{"label":"Substitute","text":"Both masses: ⟪m=2\\times 10=20\\,\\mathrm{kg}⟫.  ⟪E_{p}=20\\times 10\\times 2.0=400\\,\\mathrm{J}⟫ per drop"},{"label":"20 drops","text":"Total work ⟪=20\\times 400=8000\\,\\mathrm{J}⟫"},{"label":"Formula (heat)","text":"⟪E=mc\\Delta \\theta \\rightarrow \\Delta \\theta =E\\div (mc)⟫  (you will meet this fully in Unit 5.5)"},{"label":"Substitute","text":"⟪\\Delta \\theta =8000\\div (0.50\\times 4200)=8000\\div 2100⟫"}],"answer":"(a) 8000 J   (b) ⟪\\Delta \\theta =3.8\\,{}^{\\circ}\\mathrm{C}⟫"},{"id":"week05.5.1.e2","title":"Waterfall heating","question":"Water falls 50 m down a waterfall. If all its gravitational potential energy becomes heat in the water, how much warmer is the water at the bottom? (⟪c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫, ⟪g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1}⟫)","steps":[{"label":"Idea","text":"Loss of PE = heat gained:  ⟪mgh=mc\\Delta \\theta⟫"},{"label":"Cancel m","text":"The mass cancels!  ⟪gh=c\\Delta \\theta \\rightarrow \\Delta \\theta =gh\\div c⟫"},{"label":"Substitute","text":"⟪\\Delta \\theta =(10\\times 50)\\div 4200=500\\div 4200⟫"},{"label":"Answer","text":"0.119 °C → 2 s.f."}],"answer":"⟪\\Delta \\theta \\approx 0.12\\,{}^{\\circ}\\mathrm{C}⟫ — tiny, which is why Joule needed a very sensitive thermometer."},{"id":"week05.5.1.e3","title":"Explaining Rumford's evidence","question":"Explain how Rumford's cannon-boring observations argued against the caloric theory. [3 marks]","steps":[{"label":"Point 1","text":"Caloric theory said a body holds a fixed amount of caloric, so heat from boring should eventually run out — but heat was produced for as long as the boring continued (unlimited)."},{"label":"Point 2","text":"A blunt drill that removed very little metal produced more heat, not less."},{"label":"Point 3","text":"So heat came from the work done against friction (motion), not from a fluid stored in the metal."}],"answer":"Heat is produced by work/motion and is not a conserved fluid — supporting the kinetic theory."}]},"tryit":[{"id":"week05.5.1.p1","kind":"self","q":"State what the caloric theory said heat was.","marks":1,"level":1,"lines":2,"scheme":"An invisible, weightless fluid (caloric) that flowed from hot bodies to cold bodies (1).","points":[{"text":"An invisible, weightless fluid (caloric) that flowed from hot bodies to cold bodies","marks":1}],"section":"try","hint":{"text":"Look back at Example 3 (Explaining Rumford's evidence). Start like this: Point 1: Caloric theory said a body holds a fixed amount of caloric, so heat from boring should eventually run out — but heat was produced for as long as the boring continued (unlimited).","from":3}},{"id":"week05.5.1.p2","kind":"self","q":"State what the kinetic theory says heat is.","marks":1,"level":1,"lines":2,"scheme":"A form of energy — the energy of the random motion of the particles of a substance (1).","points":[{"text":"A form of energy — the energy of the random motion of the particles of a substance","marks":1}],"section":"try"}],"practice":[{"id":"week05.5.1.p3","kind":"self","q":"Give TWO differences between the caloric theory and the kinetic theory of heat.","marks":2,"level":2,"lines":4,"scheme":"Caloric: heat is a fluid; kinetic: heat is energy of moving particles (1). Caloric: heat cannot be created/destroyed; kinetic: heat can be produced by doing work (e.g. friction) — total energy is conserved (1).","points":[{"text":"Caloric: heat is a fluid; kinetic: heat is energy of moving particles","marks":1},{"text":"Caloric: heat cannot be created/destroyed; kinetic: heat can be produced by doing work (e.g. friction) — total energy is conserved","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Explaining Rumford's evidence). Start like this: Point 1: Caloric theory said a body holds a fixed amount of caloric, so heat from boring should eventually run out — but heat was produced for as long as the boring continued (unlimited).","from":3}},{"id":"week05.5.1.p4","kind":"self","q":"Rub your hands together quickly. They get warm. Explain this using (a) the kinetic theory and (b) why it is difficult to explain using the caloric theory.","marks":3,"level":2,"lines":4,"scheme":"(a) Work is done against friction (1); this energy makes the particles of the skin vibrate faster, increasing their kinetic energy/temperature (1). (b) The heat can be produced for as long as you keep rubbing — caloric, being a fixed amount, should run out (1).","points":[{"text":"(a) Work is done against friction","marks":1},{"text":"this energy makes the particles of the skin vibrate faster, increasing their kinetic energy/temperature","marks":1},{"text":"(b) The heat can be produced for as long as you keep rubbing — caloric, being a fixed amount, should run out","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Explaining Rumford's evidence). Start like this: Point 1: Caloric theory said a body holds a fixed amount of caloric, so heat from boring should eventually run out — but heat was produced for as long as the boring continued (unlimited).","from":3}},{"id":"week05.5.1.p5","kind":"self","q":"Describe Joule's paddle-wheel experiment. Include what was measured.","marks":4,"level":3,"lines":6,"scheme":"Falling masses turned paddles in an insulated container of water (1). The paddles churned the water, doing work against friction, and the water warmed (1). The loss of PE of the masses (mgh) was measured/calculated (1) and the small temperature rise of the water was measured with a sensitive thermometer (1).","points":[{"text":"Falling masses turned paddles in an insulated container of water","marks":1},{"text":"The paddles churned the water, doing work against friction, and the water warmed","marks":1},{"text":"The loss of PE of the masses (mgh) was measured/calculated","marks":1},{"text":"and the small temperature rise of the water was measured with a sensitive thermometer","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (A Joule-type experiment). Start like this: Formula (one drop): ⟪E_{p}=mgh⟫","from":1}},{"id":"week05.5.1.p6","kind":"self","q":"Explain how Joule's experiments supported the principle of conservation of energy.","marks":2,"level":2,"lines":3,"scheme":"A fixed amount of work always produced the same amount of heat (1), so mechanical energy is converted into thermal energy and none is lost — energy is conserved (1).","points":[{"text":"A fixed amount of work always produced the same amount of heat","marks":1},{"text":"so mechanical energy is converted into thermal energy and none is lost — energy is conserved","marks":1}],"section":"practice"},{"id":"week05.5.1.p7","kind":"num","q":"In a Joule experiment a 25 kg mass falls 1.6 m, 30 times. Calculate the total work done. ⟪(g=10\\,\\mathrm{N}\\,\\mathrm{kg}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"One drop: ⟪E=mgh=25\\times 10\\times 1.6=400\\,\\mathrm{J}⟫ (1). Total ⟪=30\\times 400=12\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"One drop: ⟪E=mgh=25\\times 10\\times 1.6=400\\,\\mathrm{J}⟫","marks":1},{"text":"Total ⟪=30\\times 400=12\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":12000,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (A Joule-type experiment). Start like this: Formula (one drop): ⟪E_{p}=mgh⟫","from":1}}],"exit":[{"id":"week05.5.1.p8","kind":"num","q":"The 12 000 J in the previous question all goes into 1.2 kg of water ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫. Calculate the temperature rise.","marks":2,"level":2,"lines":3,"scheme":"⟪\\Delta \\theta =E\\div (mc)=12\\,000\\div (1.2\\times 4200)⟫ (1) ⟪=2.4\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"⟪\\Delta \\theta =E\\div (mc)=12\\,000\\div (1.2\\times 4200)⟫","marks":1},{"text":"⟪=2.4\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"num":{"value":2.4,"sf":2,"unit":"°C","unitTex":"{}^{\\circ}\\mathrm{C}"},"section":"exit"},{"id":"week05.5.1.p9","kind":"self","q":"Joule's measured temperature rise was always a little SMALLER than his calculation predicted. Suggest TWO reasons.","marks":2,"level":2,"lines":3,"scheme":"Some energy was lost as heat to the surroundings/container (1); some energy was wasted as friction in the pulleys/KE of the masses on landing/sound (1).","points":[{"text":"Some energy was lost as heat to the surroundings/container","marks":1},{"text":"some energy was wasted as friction in the pulleys/KE of the masses on landing/sound","marks":1}],"section":"exit"}],"warmup":[{"id":"week05.5.1.w1","kind":"self","q":"Write the formulas for gravitational PE and kinetic energy.","marks":1,"level":1,"scheme":"⟪\\Delta Ep=mg\\Delta h⟫;  ⟪Ek=\\tfrac{1}{2}mv^{2}⟫.","points":[{"text":"⟪\\Delta Ep=mg\\Delta h⟫;  ⟪Ek=\\tfrac{1}{2}mv^{2}⟫.","marks":1}],"section":"warmup","src":"week04.r1"},{"id":"week05.5.1.w2","kind":"self","q":"A 2 kg ball moves at 4 m/s. What is its KE?","marks":1,"level":1,"scheme":"⟪\\tfrac{1}{2}\\times 2\\times 16=16\\,\\mathrm{J}⟫.","points":[{"text":"⟪\\tfrac{1}{2}\\times 2\\times 16=16\\,\\mathrm{J}⟫.","marks":1}],"section":"warmup","src":"week04.r2"},{"id":"week05.5.1.w3","kind":"self","q":"Define power and give its unit.","marks":1,"level":1,"scheme":"Rate of doing work / energy conversion; watt (J s⁻¹).","points":[{"text":"Rate of doing work / energy conversion; watt (J s⁻¹).","marks":1}],"section":"warmup","src":"week04.r3"},{"id":"week05.5.1.w4","kind":"num","q":"A machine gives 300 J useful output from 400 J input. Efficiency?","marks":1,"level":1,"scheme":"75%.","points":[{"text":"75%.","marks":1}],"num":{"value":75,"sf":2,"unit":"%","unitTex":"\\%"},"section":"warmup","src":"week04.r4"},{"id":"week05.5.1.w5","kind":"self","q":"State Archimedes' principle.","marks":1,"level":1,"scheme":"An object wholly or partly immersed in a fluid experiences an upthrust equal to the weight of fluid displaced.","points":[{"text":"An object wholly or partly immersed in a fluid experiences an upthrust equal to the weight of fluid displaced.","marks":1}],"section":"warmup","src":"week04.r5"}],"quickStart":[{"type":"h","text":"1. Energy and work (Week 4)"},{"type":"p","text":"Energy is the ability to do work. Unit: **joule (J)**. Energy cannot be created or destroyed, only changed from one form to another. Gravitational potential energy: ⟪\\boldsymbol{E_{p}=mgh}⟫. Kinetic energy: ⟪\\boldsymbol{E_{k}=\\tfrac{1}{2}mv^{2}}⟫."},{"type":"h","text":"2. Power (Week 4)"},{"type":"formula","tex":"P=E/t\\text{ so }E=P\\times t","where":["⟪P⟫ = power (W);  E = energy (J);  t = time (s)","⟪1\\,\\mathrm{W}⟫ = 1 J s^−1^. A 2000 W kettle gives 2000 J of energy every second."],"label":"POWER"},{"type":"warn","text":"Time must be in **seconds**: 5 minutes ⟪=5\\times 60=300\\,\\mathrm{s}⟫."},{"type":"h","text":"3. Electrical energy from a heater (NEW — you will meet this fully in Week 9)"},{"type":"formula","tex":"E=V\\times I\\times t","where":["⟪V⟫ = voltage across the heater (V);  I = current through it (A);  t = time (s);  same as ⟪E=Pt⟫ because ⟪P=VI⟫","Example: 12 V, 4.0 A for ⟪5.0\\,\\mathrm{min}\\rightarrow E=12\\times 4.0\\times 300=14\\,400\\,\\mathrm{J}⟫"],"label":"ENERGY SUPPLIED BY A HEATER"},{"type":"h","text":"4. Temperature change Δθ"},{"type":"p","text":"Δθ (\"delta theta\") means **change in temperature** = final temperature − initial temperature. A rise from 25 °C to 60 °C gives ⟪\\Delta \\theta =35\\,{}^{\\circ}\\mathrm{C}⟫. (A change of ⟪1\\,{}^{\\circ}\\mathrm{C}=a⟫ change of 1 K.)"},{"type":"fill","text":"Try it: water cools from 85 °C to 30 °C.  Δθ = ","lines":1},{"type":"fill","text":"Try it: a 60 W heater runs for 2 minutes. Energy supplied E = ","lines":1}],"n":30},{"id":"week05.5.2","kind":"unit","unit":"5.2","title":"Temperature, Thermometers and the Celsius Scale","titleText":"Temperature, Thermometers and the Celsius Scale","goals":[{"code":"B2.1","text":"Relate temperature to the direction of net thermal energy transfer"},{"code":"B2.2","text":"Identify physical properties which vary with temperature and may be used as the basis for measuring temperature (thermometric properties)"},{"code":"B2.3","text":"Relate the use of a thermometer to its design (liquid-in-glass laboratory, clinical and thermocouple thermometers: range, sensitivity, responsiveness)"},{"code":"B2.4","text":"Define the fixed points on the Celsius scale"},{"code":"B2.5","text":"Relate temperature to the kinetic energy of molecules"}],"codes":["B2.1","B2.2","B2.3","B2.4","B2.5"],"words":[{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Thermal equilibrium","def":"The state when two bodies in contact are at the same temperature, so there is no net heat flow."},{"term":"Thermometric property","def":"A physical property that varies continuously and measurably with temperature."},{"term":"Sensitivity","def":"How large a change in reading a thermometer gives for a 1 °C change in temperature."},{"term":"Responsiveness","def":"How quickly a thermometer reacts to a change in temperature."},{"term":"Range","def":"The lowest to highest temperature a thermometer can measure."},{"term":"Fixed point","def":"A reproducible temperature used to calibrate a scale: ice point 0 °C, steam point 100 °C."},{"term":"Bimetallic strip","def":"Two different metals bonded together; it bends on heating because they expand by different amounts."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"learn":{"notes":[{"type":"h","text":"Heat and temperature are NOT the same"},{"type":"def","term":"Temperature","text":"a measure of the degree of hotness or coldness of a body. It is related to the **average kinetic energy** of the particles of the body. Units: °C or K (kelvin)."},{"type":"def","term":"Heat","text":"energy transferred from a hotter body to a colder body because of a difference in temperature. Unit: J."},{"type":"p","text":"A swimming pool at 30 °C has a lower temperature than a cup of tea at 80 °C, but it contains far **more** thermal energy because it has far more particles. Temperature tells you **how fast, on average,** the particles move — not how much energy there is in total."},{"type":"h","text":"Temperature decides which way heat flows (B2.1)"},{"type":"img","src":"img/week05/heat_flow","alt":"Figure 5.2 — Net thermal energy always flows from the higher temperature to the lower temperature","caption":"Figure 5.2 — Net thermal energy always flows from the higher temperature to the lower temperature","width":4.2,"w":958,"h":414},{"type":"bullets","items":["**Net** thermal energy always flows from a body at a **higher temperature** to a body at a **lower temperature** — never the other way by itself.","The flow continues until both bodies reach the **same temperature**. They are then in **thermal equilibrium** and there is no net flow.","It is the **temperature difference**, not the amount of energy, that decides the direction. Heat flows from a hot nail (small, 200 °C) into a bucket of water (large, 30 °C), even though the bucket holds more energy."]},{"type":"remember","text":"\"Cold\" does not flow. When you hold ice, heat flows **out of your hand into the ice** — that is why your hand feels cold."},{"type":"h","text":"Temperature and the kinetic energy of molecules (B2.5)"},{"type":"bullets","items":["The particles of every substance are always moving (vibrating in solids; moving about in liquids and gases).","The **higher the temperature, the greater the average kinetic energy** of the particles — they move or vibrate faster.","When a body is heated (and does not change state), the energy goes into increasing the KE of its particles, so the temperature rises.","At **absolute zero **⟪\\boldsymbol{(0\\,\\mathrm{K}=-273\\,{}^{\\circ}\\mathrm{C})}⟫ the particles have the minimum possible kinetic energy. Nothing can be colder. (More on the kelvin scale in Week 6.)"]},{"type":"h","text":"Thermometric properties (B2.2)"},{"type":"def","term":"Thermometric property","text":"a physical property of a substance that changes continuously and measurably with temperature, so it can be used to measure temperature."},{"type":"table","headers":["Thermometric property","Thermometer that uses it"],"rows":[["Volume (length of column) of a liquid","Liquid-in-glass thermometer (mercury or alcohol)"],["Electrical resistance of a metal wire","Resistance thermometer (platinum)"],["Resistance of a semiconductor","Thermistor thermometer (digital thermometers)"],["e.m.f. (voltage) between two different metals","Thermocouple"],["Pressure of a gas at constant volume","Constant-volume gas thermometer"],["Colour","Liquid-crystal strip thermometer (forehead strips, aquarium strips)"],["Shape of a bimetallic strip (bending)","Dial/oven thermometer"]]},{"type":"p","text":"A **good** thermometric property must: change by a **large, measurable amount** for a small temperature change; change **continuously** (and ideally uniformly) with temperature; and have a **single value** at each temperature over the range needed."},{"type":"h","text":"Design of thermometers: range, sensitivity, responsiveness (B2.3)"},{"type":"def","term":"Range","text":"the lowest to the highest temperature the thermometer can measure."},{"type":"def","term":"Sensitivity","text":"how large a change in reading (e.g. length of liquid column) is produced by a 1 °C change in temperature. A sensitive thermometer can show very small temperature changes."},{"type":"def","term":"Responsiveness","text":"how quickly the thermometer reacts to a change in temperature (how fast it gives a steady reading)."},{"type":"img","src":"img/week05/thermometers","alt":"Figure 5.3 — A laboratory liquid-in-glass thermometer (top) and a clinical thermometer (bottom)","caption":"Figure 5.3 — A laboratory liquid-in-glass thermometer (top) and a clinical thermometer (bottom)","width":5.6,"w":1252,"h":589},{"type":"table","headers":["Design feature","Why it is there"],"rows":[["Thin-walled glass bulb","Heat passes through quickly → more **responsive**"],["Narrow (fine) capillary bore","A small volume change gives a long movement of the thread → more **sensitive**"],["Large bulb (more liquid)","Bigger volume change per °C → more **sensitive** (but slower to respond)"],["Vacuum above the liquid","Liquid can expand freely without compressing air"],["Thick glass stem","Strength; in a clinical thermometer the stem is shaped to act as a magnifying lens"]]},{"type":"table","headers":["","Mercury","Alcohol (coloured ethanol)"],"rows":[["Freezing point / boiling point","⟪-39\\,{}^{\\circ}\\mathrm{C}/357\\,{}^{\\circ}\\mathrm{C}⟫","⟪-115\\,{}^{\\circ}\\mathrm{C}/78\\,{}^{\\circ}\\mathrm{C}⟫"],["Good for","High temperatures; laboratory use","Very low temperatures (e.g. polar regions, freezers)"],["Other points","Opaque/shiny so easy to see; does not wet (stick to) glass; good conductor so responds quickly; expands uniformly; **poisonous**","Expands about 6 times more than mercury (more sensitive); cheap; must be dyed; wets the glass; cannot measure 100 °C"]]},{"type":"h","text":"The clinical thermometer"},{"type":"bullets","items":["Short **range: about 35 °C to 42 °C** — only the temperatures a human body can have. This lets the scale be spread out so it is very **sensitive** (reads to 0.1 °C).","A **constriction** (narrow kink) in the bore near the bulb. When the thermometer is removed from the mouth, the mercury thread **breaks** at the constriction, so the reading **stays** and can be read later. It must be **shaken** to return the mercury to the bulb.","**Thin-walled bulb** so it responds quickly.","**Triangular stem** that acts as a lens to magnify the thin thread.","Normal body temperature ≈ **37 °C**. Today many clinics use digital (thermistor) or infra-red thermometers."]},{"type":"warn","text":"Never sterilise a clinical thermometer in boiling water: 100 °C is far above its range and the expanding mercury will crack the glass. Wipe it with cold antiseptic instead.","label":"WHY?"},{"type":"h","text":"The thermocouple thermometer"},{"type":"img","src":"img/week05/thermocouple","alt":"Figure 5.4 — A thermocouple: two different metals joined at a hot junction and a cold reference junction","caption":"Figure 5.4 — A thermocouple: two different metals joined at a hot junction and a cold reference junction","width":4.6,"w":1061,"h":368},{"type":"bullets","items":["Two wires of **different metals** (e.g. copper and iron) are joined at two junctions.","When the two junctions are at **different temperatures**, a small **e.m.f. (voltage)** is produced, read on a millivoltmeter. The bigger the temperature difference, the bigger the e.m.f.","One junction (the **cold/reference junction**) is kept at a known temperature, e.g. in melting ice at 0 °C. The other (the **hot junction**) is the probe."]},{"type":"table","headers":["Advantage of a thermocouple","Reason"],"rows":[["Very wide range (about −200 °C to 1500 °C)","Metals do not boil/melt like liquids — used in furnaces, kilns, engines"],["Very responsive (fast)","Junction is tiny, so it has a very small heat capacity and heats up quickly"],["Measures the temperature at a point","The junction is very small"],["Can be read remotely / connected to a computer","Gives an electrical output; long wires can be used"]]},{"type":"p","text":"**Disadvantages:** the e.m.f. is small and not exactly proportional to temperature, so it must be calibrated; it needs a meter."},{"type":"h","text":"Fixed points of the Celsius scale (B2.4)"},{"type":"def","term":"Fixed point","text":"a single, reproducible temperature at which some physical change always happens, used to calibrate a thermometer scale."},{"type":"def","term":"Lower fixed point (ice point), 0 °C","text":"the temperature of **pure melting ice** at standard atmospheric pressure."},{"type":"def","term":"Upper fixed point (steam point), 100 °C","text":"the temperature of **steam above pure boiling water** at standard atmospheric pressure (760 mm Hg / 1 atm)."},{"type":"img","src":"img/week05/fixed_points","alt":"Figure 5.5 — Finding the ice point (left) and the steam point (right) of an unmarked thermometer","caption":"Figure 5.5 — Finding the ice point (left) and the steam point (right) of an unmarked thermometer","width":5.4,"w":1229,"h":694},{"type":"p","text":"**Calibrating an unmarked thermometer:** mark the column length at the ice point (l~0~) and at the steam point (l~100~); divide the distance between them into 100 equal degrees. Then for any length l~θ~:"},{"type":"formula","tex":"\\theta =(l_{\\theta}-l_{0})\\div (l_{100}-l_{0})\\times 100\\,{}^{\\circ}\\mathrm{C}","where":["⟪l_{0}⟫ = length at ice point;  l~100~ = length at steam point;  l~θ~ = length at the unknown temperature","The same method works for any thermometric property X: ⟪\\theta =(X_{\\theta}-X_{0})\\div (X_{100}-X_{0})\\times 100⟫"],"label":"TEMPERATURE FROM A THERMOMETRIC PROPERTY"},{"type":"tip","text":"Why steam ABOVE boiling water and not in the water? Impurities dissolved in the water raise its boiling point, but the steam temperature depends only on pressure. Why pure ice? Impurities (e.g. salt) lower the melting point."}],"examples":[{"id":"week05.5.2.e1","title":"Calibrating with column length","question":"The mercury thread of an unmarked thermometer is 2.0 cm long in melting ice and 22.0 cm long in steam at 1 atm. In warm water it is 9.0 cm long. Find the temperature of the water.","steps":[{"label":"Formula","text":"⟪\\theta =(l_{\\theta}-l_{0})\\div (l_{100}-l_{0})\\times 100⟫"},{"label":"Substitute","text":"⟪\\theta =(9.0-2.0)\\div (22.0-2.0)\\times 100=7.0\\div 20.0\\times 100⟫"},{"label":"Answer","text":"⟪\\theta =35\\,{}^{\\circ}\\mathrm{C}⟫"}],"answer":"⟪\\theta =35\\,{}^{\\circ}\\mathrm{C}⟫"},{"id":"week05.5.2.e2","title":"Using resistance as the thermometric property","question":"A platinum wire has resistance 20.0 Ω at the ice point and 27.5 Ω at the steam point. Its resistance in a liquid is 23.0 Ω. Find the temperature of the liquid (assume resistance varies uniformly).","steps":[{"label":"Formula","text":"⟪\\theta =(R_{\\theta}-R_{0})\\div (R_{100}-R_{0})\\times 100⟫"},{"label":"Substitute","text":"⟪\\theta =(23.0-20.0)\\div (27.5-20.0)\\times 100=3.0\\div 7.5\\times 100⟫"},{"label":"Answer","text":"⟪\\theta =40\\,{}^{\\circ}\\mathrm{C}⟫"}],"answer":"⟪\\theta =40\\,{}^{\\circ}\\mathrm{C}⟫"},{"id":"week05.5.2.e3","title":"Choosing a thermometer","question":"Choose the most suitable thermometer for: (a) the temperature of molten iron in a furnace (1500 °C); (b) a child with a fever; (c) the air in Antarctica (−60 °C). Give a reason each time.","steps":[{"label":"(a)","text":"Thermocouple — mercury would boil (357 °C) and glass would melt; thermocouple range reaches about 1500 °C."},{"label":"(b)","text":"Clinical thermometer — narrow range 35–42 °C, very sensitive (0.1 °C), constriction keeps the reading."},{"label":"(c)","text":"Alcohol-in-glass thermometer — alcohol freezes at −115 °C; mercury would freeze at −39 °C."}],"answer":"(a) thermocouple  (b) clinical  (c) alcohol-in-glass"}]},"tryit":[{"id":"week05.5.2.p1","kind":"self","q":"Define **temperature**.","marks":1,"level":1,"lines":2,"scheme":"A measure of the degree of hotness of a body / related to the average kinetic energy of its particles (1).","points":[{"text":"A measure of the degree of hotness of a body / related to the average kinetic energy of its particles","marks":1}],"section":"try","hint":{"text":"Look back at Example 1 (Calibrating with column length). Start like this: Formula: ⟪\\theta =(l_{\\theta}-l_{0})\\div (l_{100}-l_{0})\\times 100⟫","from":1}},{"id":"week05.5.2.p2","kind":"self","q":"A hot iron nail at 150 °C is dropped into a large tub of water at 28 °C. State the direction of the net flow of thermal energy and when it stops.","marks":2,"level":2,"lines":3,"scheme":"From the nail to the water (higher to lower temperature) (1); it stops when both reach the same temperature (thermal equilibrium) (1).","points":[{"text":"From the nail to the water (higher to lower temperature)","marks":1},{"text":"it stops when both reach the same temperature (thermal equilibrium)","marks":1}],"section":"try"}],"practice":[{"id":"week05.5.2.p3","kind":"self","q":"What happens to the average kinetic energy of the molecules of water when the water is heated from 20 °C to 60 °C?","marks":1,"level":1,"lines":2,"scheme":"It increases — the molecules move faster (1).","points":[{"text":"It increases — the molecules move faster","marks":1}],"section":"practice"},{"id":"week05.5.2.p4","kind":"self","q":"State THREE thermometric properties.","marks":3,"level":2,"lines":3,"scheme":"Any three (1 each): volume/length of a liquid column; resistance of a wire/thermistor; e.m.f. of a thermocouple; pressure of a gas at constant volume; colour of liquid crystal.","points":[{"text":"Any three (1 each): volume/length of a liquid column; resistance of a wire/thermistor; e.m.f. of a thermocouple; pressure of a gas at constant volume; colour of liquid crystal.","marks":3,"each":true}],"section":"practice","hint":{"text":"Look back at Example 2 (Using resistance as the thermometric property). Start like this: Formula: ⟪\\theta =(R_{\\theta}-R_{0})\\div (R_{100}-R_{0})\\times 100⟫","from":2}},{"id":"week05.5.2.p5","kind":"self","q":"Define the lower and upper fixed points of the Celsius scale.","marks":2,"level":2,"lines":4,"scheme":"Lower (ice point, 0 °C): temperature of pure melting ice at standard atmospheric pressure (1). Upper (steam point, 100 °C): temperature of steam above pure water boiling at standard atmospheric pressure (1).","points":[{"text":"Lower (ice point, 0 °C): temperature of pure melting ice at standard atmospheric pressure","marks":1},{"text":"Upper (steam point, 100 °C): temperature of steam above pure water boiling at standard atmospheric pressure","marks":1}],"section":"practice"},{"id":"week05.5.2.p6","kind":"self","q":"Explain how EACH feature affects a liquid-in-glass thermometer: (a) a narrower bore; (b) a thinner bulb wall.","marks":2,"level":2,"lines":4,"scheme":"(a) Increases sensitivity — the same volume change produces a longer movement of the thread (1). (b) Increases responsiveness — heat passes through faster so it reaches a steady reading sooner (1).","points":[{"text":"(a) Increases sensitivity — the same volume change produces a longer movement of the thread","marks":1},{"text":"(b) Increases responsiveness — heat passes through faster so it reaches a steady reading sooner","marks":1}],"section":"practice"},{"id":"week05.5.2.p7","kind":"self","q":"Give TWO features of a clinical thermometer and explain the purpose of each.","marks":4,"level":3,"lines":5,"scheme":"Constriction (1): the thread breaks there so the reading is kept after removal from the patient (1). Short range 35–42 °C (1): scale spread out → high sensitivity, reads to 0.1 °C (1). [Also accept thin bulb → responsive; triangular stem → magnifies thread.]","points":[{"text":"Constriction","marks":1},{"text":": the thread breaks there so the reading is kept after removal from the patient","marks":1},{"text":"Short range 35–42 °C","marks":1},{"text":": scale spread out → high sensitivity, reads to 0.1 °C. [Also accept thin bulb → responsive; triangular stem → magnifies thread.]","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Choosing a thermometer). Start like this: (a): Thermocouple — mercury would boil (357 °C) and glass would melt; thermocouple range reaches about 1500 °C.","from":3}},{"id":"week05.5.2.p8","kind":"self","q":"Give TWO reasons why a thermocouple is used to measure the temperature of a car exhaust instead of a mercury thermometer.","marks":2,"level":2,"lines":3,"scheme":"Wide range — can measure very high temperatures (above mercury's boiling point) (1). Very responsive / small junction / can be read remotely by wires (1).","points":[{"text":"Wide range — can measure very high temperatures (above mercury's boiling point)","marks":1},{"text":"Very responsive / small junction / can be read remotely by wires","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Calibrating with column length). Start like this: Formula: ⟪\\theta =(l_{\\theta}-l_{0})\\div (l_{100}-l_{0})\\times 100⟫","from":1}}],"exit":[{"id":"week05.5.2.p9","kind":"self","q":"An unmarked thermometer has a thread 4.0 cm long at 0 °C and 24.0 cm at 100 °C. (a) What length corresponds to 60 °C? (b) What temperature does a thread of 12.5 cm show?","marks":4,"level":3,"lines":5,"scheme":"Length per ⟪{}^{\\circ}\\mathrm{C}=(24.0-4.0)\\div 100=0.20\\,\\mathrm{cm}⟫ per °C (1). (a) ⟪l=4.0+60\\times 0.20=16.0\\,\\mathrm{cm}⟫ (1). (b) ⟪\\theta =(12.5-4.0)\\div 20.0\\times 100⟫ (1) ⟪=42.5\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"Length per ⟪{}^{\\circ}\\mathrm{C}=(24.0-4.0)\\div 100=0.20\\,\\mathrm{cm}⟫ per °C","marks":1},{"text":"(a) ⟪l=4.0+60\\times 0.20=16.0\\,\\mathrm{cm}⟫","marks":1},{"text":"(b) ⟪\\theta =(12.5-4.0)\\div 20.0\\times 100⟫","marks":1},{"text":"⟪=42.5\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"section":"exit"},{"id":"week05.5.2.p10","kind":"self","q":"Why is alcohol, not mercury, used in thermometers in very cold countries, and why can an alcohol thermometer NOT be used to find the steam point?","marks":2,"level":2,"lines":3,"scheme":"Alcohol freezes at −115 °C, mercury at −39 °C, so mercury would freeze (1). Alcohol boils at 78 °C, below 100 °C (1).","points":[{"text":"Alcohol freezes at −115 °C, mercury at −39 °C, so mercury would freeze","marks":1},{"text":"Alcohol boils at 78 °C, below 100 °C","marks":1}],"section":"exit"}],"warmup":[{"id":"week05.5.2.w1","kind":"self","q":"State what the caloric theory said heat was.","marks":1,"level":1,"lines":2,"scheme":"An invisible, weightless fluid (caloric) that flowed from hot bodies to cold bodies (1).","points":[{"text":"An invisible, weightless fluid (caloric) that flowed from hot bodies to cold bodies","marks":1}],"section":"warmup","src":"week05.5.1.p1"},{"id":"week05.5.2.w2","kind":"self","q":"State what the kinetic theory says heat is.","marks":1,"level":1,"lines":2,"scheme":"A form of energy — the energy of the random motion of the particles of a substance (1).","points":[{"text":"A form of energy — the energy of the random motion of the particles of a substance","marks":1}],"section":"warmup","src":"week05.5.1.p2"}],"n":31},{"id":"week05.5.3","kind":"unit","unit":"5.3","title":"Solids, Liquids and Gases: The Kinetic Theory of Matter","titleText":"Solids, Liquids and Gases: The Kinetic Theory of Matter","goals":[{"code":"B2.6","text":"Distinguish among solids, liquids and gases"},{"code":"B2.7","text":"Use the kinetic theory to explain the macroscopic properties of solids, liquids and gases"}],"codes":["B2.6","B2.7"],"words":[{"term":"Kinetic theory","def":"Matter is made of particles in constant random motion; heat is the energy of this motion."},{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Brownian motion","def":"Random zig-zag motion of tiny visible particles caused by bombardment by invisible fluid molecules."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"learn":{"notes":[{"type":"h","text":"The kinetic theory of matter"},{"type":"p","text":"The kinetic theory explains the properties we can see and measure (the **macroscopic** properties: shape, volume, density, compressibility, pressure) using what the tiny particles are doing (the **microscopic** picture). Its main ideas:"},{"type":"steps","items":["All matter is made of very small particles (atoms or molecules).","The particles are in **constant, random motion**.","There are **forces of attraction** between particles. The closer they are, the stronger the forces (at very short distances they repel).","The particles have kinetic energy. The **higher the temperature, the faster they move** (greater average KE).","In a gas the collisions of particles with each other and with the walls are **perfectly elastic** (no KE lost)."]},{"type":"img","src":"img/week05/states_particles","alt":"Figure 5.6 — Arrangement of particles in a solid, a liquid and a gas","caption":"Figure 5.6 — Arrangement of particles in a solid, a liquid and a gas","width":5.8,"w":1386,"h":514},{"type":"h","text":"Comparing the three states (B2.6)"},{"type":"table","headers":["Property","Solid","Liquid","Gas"],"rows":[["Arrangement","Regular pattern (lattice), packed closely","Irregular, close together","Random, far apart"],["Spacing","Very close (touching)","Close (slightly more than solid)","Very far apart (about 10 × diameter)"],["Motion","Vibrate about fixed positions","Move about, sliding past each other","Move quickly and freely in all directions"],["Forces between particles","Very strong","Strong (weaker than solid)","Very weak (almost none)"],["Shape","Fixed shape","Takes shape of container","Fills whole container"],["Volume","Fixed","Fixed","Not fixed — fills container"],["Compressibility","Almost incompressible","Almost incompressible","Easily compressed"],["Density","High","High (usually a bit lower than solid)","Very low"],["Can it flow?","No","Yes","Yes"]]},{"type":"h","text":"Using kinetic theory to explain properties (B2.7)"},{"type":"table","headers":["Observation (macroscopic)","Kinetic theory explanation (microscopic)"],"rows":[["A solid has a fixed shape","Strong forces hold particles in fixed positions; they can only vibrate"],["A liquid flows and takes the shape of its container","Forces are strong enough to keep particles close (fixed volume) but particles can slide past each other"],["A gas fills any container","Forces are very weak, particles move fast and randomly in all directions until they spread through the whole space"],["Gases are easily compressed; solids and liquids are not","Large spaces between gas particles can be squeezed smaller; in solids/liquids particles are already touching"],["Gases have very low density","Few particles (little mass) in a given volume because they are far apart"],["A gas exerts pressure on its container","Particles collide with the walls; each collision exerts a force; many collisions per second over the wall area give pressure ⟪(p=F/A)⟫"],["Smells spread through a room (diffusion)","Moving gas particles collide and spread from high to low concentration"],["Heating a gas in a sealed can raises its pressure","Particles move faster → hit the walls harder and more often"]]},{"type":"h","text":"Evidence for moving particles: Brownian motion"},{"type":"p","text":"When smoke is viewed under a microscope in a **smoke cell**, the bright smoke specks move in a **jerky, random, zig-zag** way. This is **Brownian motion** (first seen by Robert Brown with pollen grains in water, 1827)."},{"type":"bullets","items":["The smoke specks are being hit, unevenly, by **invisible, fast-moving air molecules** from all sides.","At any instant more molecules hit one side than the other, so the speck is pushed in a random direction.","If the air is warmed, the motion becomes **more vigorous** — the molecules move faster.","This is strong evidence that air is made of particles in **constant random motion**."]},{"type":"h","text":"Changes of state in particle terms"},{"type":"table","headers":["Change","What the particles do"],"rows":[["Melting (solid → liquid)","Particles gain enough energy to break free of fixed positions; they can now move past one another"],["Boiling (liquid → gas)","Particles gain enough energy to overcome almost all the attractive forces and escape far apart"],["Freezing / condensing","The reverse — particles lose energy and attractive forces pull them back together"]]},{"type":"remember","text":"During a change of state, the energy supplied breaks bonds (increases the **potential energy** of the particles), NOT their kinetic energy — so the temperature stays constant (see Unit 5.6)."},{"type":"warn","text":"Particles do not get bigger, hotter or softer themselves. When something is heated it is the **motion and spacing** of the particles that change, not the particles.","label":"COMMON MISTAKE"}],"examples":[{"id":"week05.5.3.e1","title":"Why a gas is compressible","question":"Use the kinetic theory to explain why air in a bicycle pump can be compressed easily but water cannot. [3 marks]","steps":[{"label":"Gas","text":"Air particles are very far apart with large empty spaces between them (1)."},{"label":"Compressing","text":"Pushing the piston reduces the spaces, so the particles move closer together (1)."},{"label":"Liquid","text":"Water particles are already very close/touching; there is almost no space to remove, so it is almost incompressible (1)."}],"answer":"Large spaces between gas particles; virtually none between liquid particles."},{"id":"week05.5.3.e2","title":"Gas pressure","question":"Explain, in terms of particles, how a gas exerts a pressure on the walls of its container, and why the pressure rises when the gas is heated at constant volume. [4 marks]","steps":[{"label":"Collisions","text":"Gas particles move randomly and collide with the walls (1)."},{"label":"Force","text":"Each collision changes the momentum of the particle, producing a force on the wall; force per unit area = pressure (1)."},{"label":"Heating","text":"Heating increases the average KE, so the particles move faster (1)."},{"label":"Result","text":"They hit the walls more often and harder (with greater force), so the pressure increases (1)."}],"answer":"Pressure is caused by particle collisions with the walls; faster particles → more frequent, harder collisions → higher pressure."},{"id":"week05.5.3.e3","title":"Describing Brownian motion","question":"A student looks at smoke in a smoke cell through a microscope. (a) Describe what she sees. (b) Explain it. (c) State what changes if the cell is warmed.","steps":[{"label":"(a) See","text":"Bright specks of smoke moving in a random, jerky, zig-zag way."},{"label":"(b) Explain","text":"The smoke particles are bombarded unevenly by much smaller, invisible, fast-moving air molecules."},{"label":"(c) Warmer","text":"The motion becomes more rapid/vigorous because the air molecules move faster."}],"answer":"Random zig-zag motion caused by uneven bombardment by air molecules; faster when warmer."}]},"tryit":[{"id":"week05.5.3.p1","kind":"self","q":"Describe the arrangement and motion of the particles in a solid.","marks":2,"level":2,"lines":3,"scheme":"Closely packed in a regular pattern/fixed positions (1); vibrate about fixed positions (1).","points":[{"text":"Closely packed in a regular pattern/fixed positions","marks":1},{"text":"vibrate about fixed positions","marks":1}],"section":"try","hint":{"text":"Look back at Example 3 (Describing Brownian motion). Start like this: (a) See: Bright specks of smoke moving in a random, jerky, zig-zag way.","from":3}},{"id":"week05.5.3.p2","kind":"self","q":"State TWO differences between a liquid and a gas in terms of their particles.","marks":2,"level":2,"lines":3,"scheme":"Liquid particles are close together, gas particles far apart (1). Forces between liquid particles are strong; between gas particles very weak / liquid particles slide past each other, gas particles move freely and fast (1).","points":[{"text":"Liquid particles are close together, gas particles far apart","marks":1},{"text":"Forces between liquid particles are strong; between gas particles very weak / liquid particles slide past each other, gas particles move freely and fast","marks":1}],"section":"try","hint":{"text":"Look back at Example 2 (Gas pressure). Start like this: Collisions: Gas particles move randomly and collide with the walls (1).","from":2}}],"practice":[{"id":"week05.5.3.p3","kind":"self","q":"Copy and complete: A gas has ……… shape and ……… volume; a liquid has ……… shape and ……… volume.","marks":2,"level":2,"lines":2,"scheme":"Gas: no fixed shape, no fixed volume (1). Liquid: no fixed shape, fixed volume (1).","points":[{"text":"Gas: no fixed shape, no fixed volume","marks":1},{"text":"Liquid: no fixed shape, fixed volume","marks":1}],"section":"practice"},{"id":"week05.5.3.p4","kind":"self","q":"Use the kinetic theory to explain why a solid has a fixed shape.","marks":2,"level":2,"lines":3,"scheme":"Particles are held in fixed positions by strong forces of attraction (1); they can only vibrate, not move past each other (1).","points":[{"text":"Particles are held in fixed positions by strong forces of attraction","marks":1},{"text":"they can only vibrate, not move past each other","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Why a gas is compressible). Start like this: Gas: Air particles are very far apart with large empty spaces between them (1).","from":1}},{"id":"week05.5.3.p5","kind":"self","q":"Explain why the density of steam is much lower than the density of water.","marks":2,"level":2,"lines":3,"scheme":"In steam the molecules are very far apart (1), so there is much less mass in each unit of volume (1).","points":[{"text":"In steam the molecules are very far apart","marks":1},{"text":"so there is much less mass in each unit of volume","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Why a gas is compressible). Start like this: Gas: Air particles are very far apart with large empty spaces between them (1).","from":1}},{"id":"week05.5.3.p6","kind":"self","q":"Perfume is sprayed in one corner of a room. After a few minutes it can be smelled across the room. Explain using the kinetic theory.","marks":2,"level":2,"lines":3,"scheme":"Perfume molecules evaporate and move randomly at high speed (1); they collide with air molecules and spread out (diffuse) from high to low concentration (1).","points":[{"text":"Perfume molecules evaporate and move randomly at high speed","marks":1},{"text":"they collide with air molecules and spread out (diffuse) from high to low concentration","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Why a gas is compressible). Start like this: Gas: Air particles are very far apart with large empty spaces between them (1).","from":1}},{"id":"week05.5.3.p7","kind":"self","q":"Explain why a sealed aerosol can may explode if left in a hot car.","marks":3,"level":2,"lines":4,"scheme":"Temperature rises so gas particles gain kinetic energy/move faster (1); they hit the walls more often and with greater force (1); pressure increases until the can bursts (1).","points":[{"text":"Temperature rises so gas particles gain kinetic energy/move faster","marks":1},{"text":"they hit the walls more often and with greater force","marks":1},{"text":"pressure increases until the can bursts","marks":1}],"section":"practice"}],"exit":[{"id":"week05.5.3.p8","kind":"self","q":"What is Brownian motion and what does it show about the particles of air?","marks":2,"level":2,"lines":3,"scheme":"The random, zig-zag motion of tiny visible particles (e.g. smoke) suspended in a fluid (1); it shows air molecules are in constant, rapid, random motion (1).","points":[{"text":"The random, zig-zag motion of tiny visible particles (e.g. smoke) suspended in a fluid","marks":1},{"text":"it shows air molecules are in constant, rapid, random motion","marks":1}],"section":"exit"},{"id":"week05.5.3.p9","kind":"self","q":"Explain, in terms of particles and energy, what happens when ice melts.","marks":3,"level":2,"lines":4,"scheme":"Heat energy is absorbed (1); this energy is used to break/weaken the bonds holding molecules in fixed positions (increases PE, not KE) (1); molecules can then move past one another as a liquid (1).","points":[{"text":"Heat energy is absorbed","marks":1},{"text":"this energy is used to break/weaken the bonds holding molecules in fixed positions (increases PE, not KE)","marks":1},{"text":"molecules can then move past one another as a liquid","marks":1}],"section":"exit"}],"warmup":[{"id":"week05.5.3.w1","kind":"self","q":"What happens to the average kinetic energy of the molecules of water when the water is heated from 20 °C to 60 °C?","marks":1,"level":1,"lines":2,"scheme":"It increases — the molecules move faster (1).","points":[{"text":"It increases — the molecules move faster","marks":1}],"section":"warmup","src":"week05.5.2.p3"},{"id":"week05.5.3.w2","kind":"self","q":"Define **temperature**.","marks":1,"level":1,"lines":2,"scheme":"A measure of the degree of hotness of a body / related to the average kinetic energy of its particles (1).","points":[{"text":"A measure of the degree of hotness of a body / related to the average kinetic energy of its particles","marks":1}],"section":"warmup","src":"week05.5.2.p1"}],"n":32},{"id":"week05.5.4","kind":"unit","unit":"5.4","title":"Thermal Expansion and the Anomalous Expansion of Water","titleText":"Thermal Expansion and the Anomalous Expansion of Water","goals":[{"code":"B2.8","text":"Discuss the effects and applications of thermal expansion (bimetallic strip, gaps in railway lines, the anomalous expansion of water)"}],"codes":["B2.8"],"words":[{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Bimetallic strip","def":"Two different metals bonded together; it bends on heating because they expand by different amounts."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"learn":{"notes":[{"type":"h","text":"Why things expand when heated"},{"type":"p","text":"Almost all substances **expand** (get bigger) when heated and **contract** (get smaller) when cooled."},{"type":"bullets","items":["When a solid is heated, its particles gain kinetic energy and **vibrate more vigorously**.","They push one another further apart, so the **average distance between particles increases**.","So the whole object gets bigger — its length, area and volume increase. The **mass stays the same**, so the **density decreases**."]},{"type":"table","headers":["State","Amount of expansion (for the same temperature rise)"],"rows":[["Solids","Smallest — strong forces hold particles together"],["Liquids","More than solids"],["Gases","Most — very weak forces between particles"]]},{"type":"warn","text":"The particles themselves do **not** expand. The **spaces** between them get bigger.","label":"COMMON MISTAKE"},{"type":"h","text":"Problems caused by expansion — and how engineers solve them"},{"type":"table","headers":["Situation","Problem","Solution"],"rows":[["Railway lines","In hot weather the rails expand and could buckle (bend)","Leave small **gaps** between rail sections, or use long welded rails that are pre-stretched; overlapping (tapered) joints"],["Bridges and roads","Bridge expands in the day, contracts at night","**Expansion joints** (comb-like gaps) and one end on **rollers** so it can move"],["Overhead power and telephone cables","Cables contract in cold weather and could snap","Hung **slack** (they sag more on hot days)"],["Concrete pavements/roads","Slabs expand and crack","Gaps filled with soft pitch/tar between slabs"],["Thick glass","Pouring hot water in: inside expands before outside → cracks","Use thin or heat-resistant (Pyrex) glass"],["Pipes carrying steam/hot oil","Expansion causes strain at bends","**Expansion loops** in the pipe"]]},{"type":"h","text":"Useful applications of expansion"},{"type":"bullets","items":["**Bimetallic strip** — in thermostats, fire alarms, flashing indicator lights, oven thermometers (see below).","**Liquid-in-glass thermometer** — the liquid expands up the bore.","**Shrink fitting / riveting** — a metal tyre or ring is heated so it expands, slipped over a wheel, then cools and contracts to grip tightly. Hot rivets contract to pull steel plates together.","**Loosening a tight metal lid** on a glass jar — run hot water over the lid; the metal expands more than the glass."]},{"type":"h","text":"The bimetallic strip"},{"type":"p","text":"A bimetallic strip is two **different metals** (e.g. brass and iron, or brass and invar) bonded together along their length. When heated, **one metal expands more than the other** (brass expands more than iron), so the strip **bends**, with the metal that expands more on the **outside** of the curve. When cooled it bends the other way."},{"type":"img","src":"img/week05/bimetallic","alt":"Figure 5.7 — A bimetallic strip bends when heated (left). In a thermostat it switches a heater off when the temperature is too high (right).","caption":"Figure 5.7 — A bimetallic strip bends when heated (left). In a thermostat it switches a heater off when the temperature is too high (right).","width":5.8,"w":1371,"h":574},{"type":"steps","items":["Thermostat (e.g. electric iron, water heater, oven): at low temperature the strip is straight and the **contacts touch** — current flows and the heater is ON.","As the temperature rises, the strip **bends away** from the contact; the circuit is **broken** and the heater turns OFF.","As it cools the strip straightens, the contacts touch again and the heater comes back on. The temperature is kept nearly **constant**.","A screw can move the contact closer or further away to set the temperature."]},{"type":"p","text":"**Fire alarm:** the strip is arranged so that when it is heated by a fire it bends **towards** a contact, **completing** a circuit and ringing a bell."},{"type":"h","text":"The anomalous (unusual) expansion of water"},{"type":"p","text":"Most liquids contract steadily as they cool. Water is different. As water cools from room temperature it contracts until **4 °C**. Between **4 °C and 0 °C it EXPANDS** as it cools further. When it freezes to ice it expands even more (by about 9%)."},{"type":"img","src":"img/week05/water_anomalous","alt":"Figure 5.8 — Water has its smallest volume, and therefore its greatest density, at 4 °C","caption":"Figure 5.8 — Water has its smallest volume, and therefore its greatest density, at 4 °C","width":5.6,"w":1374,"h":554},{"type":"bullets","items":["Water has its **maximum density (1000 kg m^−3^) at 4 °C**.","**Ice is less dense than water**, so ice floats."]},{"type":"h","text":"Effects of water's anomalous expansion"},{"type":"img","src":"img/week05/pond","alt":"Figure 5.9 — A pond freezes from the top down","caption":"Figure 5.9 — A pond freezes from the top down","width":3.8,"w":842,"h":534},{"type":"table","headers":["Effect","Explanation"],"rows":[["Ponds and lakes freeze from the TOP down; fish survive","As surface water cools to 4 °C it becomes densest and sinks. Below 4 °C the colder water is LESS dense and stays on top, where it freezes. Ice floats and, being a poor conductor, insulates the water below, which stays at about 4 °C."],["Water pipes burst in very cold weather","Water expands as it cools below 4 °C and expands even more on freezing — the force cracks the pipe"],["Weathering of rocks","Water in cracks freezes and expands, splitting the rock"],["Bottles of water burst in a freezer","Same — expansion on freezing"],["Icebergs float with about 90% under water","Ice is slightly less dense than sea water"]]},{"type":"tip","text":"For a pond question, always say the three key points: (1) water is densest at 4 °C so it sinks to the bottom; (2) colder water (below 4 °C) is less dense, stays at the top and freezes first; (3) ice is a poor conductor/insulator so the water below does not freeze and life survives."}],"examples":[{"id":"week05.5.4.e1","title":"Gaps in railway lines","question":"Explain why gaps are left between lengths of railway track and what would happen without them. [3 marks]","steps":[{"label":"Expansion","text":"On hot days the steel rails get hot and expand (their particles vibrate more and move further apart) (1)."},{"label":"Need for gaps","text":"The gaps give the rails room to expand (1)."},{"label":"Without gaps","text":"The expanding rails would push against each other and buckle/bend, which could derail a train (1)."}],"answer":"Gaps allow for expansion in hot weather and prevent buckling."},{"id":"week05.5.4.e2","title":"How a thermostat works","question":"A bimetallic thermostat controls an electric water heater. The strip is made of brass and iron; brass expands more. Explain how it keeps the water at a steady temperature. [4 marks]","steps":[{"label":"Cold","text":"When cool, the strip is straight and the contacts touch — the heater is on (1)."},{"label":"Heating","text":"As the temperature rises, brass expands more than iron so the strip bends (with brass on the outside) (1)."},{"label":"Switch off","text":"The strip bends away from the contact, breaking the circuit and switching the heater off (1)."},{"label":"Cycle","text":"When the water cools, the strip straightens, the contacts touch and the heater comes on again (1)."}],"answer":"Unequal expansion bends the strip, opening and closing the circuit."},{"id":"week05.5.4.e3","title":"Hot water in a thick glass","question":"Explain why a thick glass tumbler may crack when boiling water is poured into it.","steps":[{"label":"Inner surface","text":"The inner surface heats quickly and expands."},{"label":"Outer surface","text":"Glass is a poor conductor, so the outer surface stays cool and does not expand."},{"label":"Result","text":"The uneven expansion creates a large strain (stress) in the glass, so it cracks."}],"answer":"Uneven expansion of inside and outside → strain → crack."}]},"tryit":[{"id":"week05.5.4.p1","kind":"self","q":"Explain, in terms of particles, why a metal rod gets longer when it is heated.","marks":2,"level":2,"lines":3,"scheme":"Particles gain kinetic energy and vibrate more vigorously (1); the average distance between them increases, so the rod expands (1).","points":[{"text":"Particles gain kinetic energy and vibrate more vigorously","marks":1},{"text":"the average distance between them increases, so the rod expands","marks":1}],"section":"try","hint":{"text":"Look back at Example 3 (Hot water in a thick glass). Start like this: Inner surface: The inner surface heats quickly and expands.","from":3}},{"id":"week05.5.4.p2","kind":"self","q":"When a metal block is heated, state what happens to (a) its mass, (b) its volume, (c) its density.","marks":3,"level":2,"lines":3,"scheme":"(a) Stays the same (1). (b) Increases (1). (c) Decreases (1).","points":[{"text":"(a) Stays the same","marks":1},{"text":"(b) Increases","marks":1},{"text":"(c) Decreases","marks":1}],"section":"try"}],"practice":[{"id":"week05.5.4.p3","kind":"self","q":"Why are overhead power cables hung slack instead of tight?","marks":2,"level":2,"lines":3,"scheme":"In cold weather the cables contract (1); if they were tight they could snap / pull down the poles (1).","points":[{"text":"In cold weather the cables contract","marks":1},{"text":"if they were tight they could snap / pull down the poles","marks":1}],"section":"practice"},{"id":"week05.5.4.p4","kind":"self","q":"State TWO ways in which bridges are designed to allow for expansion.","marks":2,"level":2,"lines":3,"scheme":"Expansion joints/gaps (1); one end resting on rollers (1).","points":[{"text":"Expansion joints/gaps","marks":1},{"text":"one end resting on rollers","marks":1}],"section":"practice"},{"id":"week05.5.4.p5","kind":"self","q":"A bimetallic strip is made of brass and invar. Brass expands much more than invar. Draw/describe the shape of the strip after heating and state which metal is on the outside.","marks":2,"level":2,"lines":3,"scheme":"The strip bends/curves (1) with brass on the outside of the curve (1).","points":[{"text":"The strip bends/curves","marks":1},{"text":"with brass on the outside of the curve","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (How a thermostat works). Start like this: Cold: When cool, the strip is straight and the contacts touch — the heater is on (1).","from":2}},{"id":"week05.5.4.p6","kind":"self","q":"Describe how a bimetallic strip can be used in a fire alarm.","marks":3,"level":2,"lines":4,"scheme":"The strip is fixed at one end with a contact near its free end (1). Heat from a fire makes it bend (unequal expansion) towards the contact (1), completing the circuit so the bell rings (1).","points":[{"text":"The strip is fixed at one end with a contact near its free end","marks":1},{"text":"Heat from a fire makes it bend (unequal expansion) towards the contact","marks":1},{"text":"completing the circuit so the bell rings","marks":1}],"section":"practice","hint":{"text":"Look back at Example 2 (How a thermostat works). Start like this: Cold: When cool, the strip is straight and the contacts touch — the heater is on (1).","from":2}},{"id":"week05.5.4.p7","kind":"self","q":"At what temperature is water most dense? What happens to the volume of water as it cools from 4 °C to 0 °C?","marks":2,"level":2,"lines":2,"scheme":"4 °C (1); the volume increases (it expands) (1).","points":[{"text":"4 °C","marks":1},{"text":"the volume increases (it expands)","marks":1}],"section":"practice"},{"id":"week05.5.4.p8","kind":"self","q":"Explain why fish in a pond can survive in winter even when the surface is frozen.","marks":3,"level":2,"lines":5,"scheme":"Water is densest at 4 °C so it sinks to the bottom (1); colder water is less dense and stays on top, freezing first; ice floats (1); ice is a poor conductor/insulates the water below, which stays at about 4 °C (1).","points":[{"text":"Water is densest at 4 °C so it sinks to the bottom","marks":1},{"text":"colder water is less dense and stays on top, freezing first; ice floats","marks":1},{"text":"ice is a poor conductor/insulates the water below, which stays at about 4 °C","marks":1}],"section":"practice"}],"exit":[{"id":"week05.5.4.p9","kind":"self","q":"Explain why water pipes may burst in very cold countries.","marks":2,"level":2,"lines":3,"scheme":"Water expands as it cools below 4 °C and expands further when it freezes (1); the expanding ice exerts a large force which cracks the pipe (1).","points":[{"text":"Water expands as it cools below 4 °C and expands further when it freezes","marks":1},{"text":"the expanding ice exerts a large force which cracks the pipe","marks":1}],"section":"exit"},{"id":"week05.5.4.p10","kind":"self","q":"A tight metal lid on a glass jar can be loosened by holding it under hot water. Explain.","marks":2,"level":2,"lines":3,"scheme":"The metal lid expands more than the glass (metal expands more / heats faster) (1), so the lid becomes looser on the jar (1).","points":[{"text":"The metal lid expands more than the glass (metal expands more / heats faster)","marks":1},{"text":"so the lid becomes looser on the jar","marks":1}],"section":"exit"}],"warmup":[{"id":"week05.5.4.w1","kind":"self","q":"Use the kinetic theory to explain why a solid has a fixed shape.","marks":2,"level":2,"lines":3,"scheme":"Particles are held in fixed positions by strong forces of attraction (1); they can only vibrate, not move past each other (1).","points":[{"text":"Particles are held in fixed positions by strong forces of attraction","marks":1},{"text":"they can only vibrate, not move past each other","marks":1}],"section":"warmup","src":"week05.5.3.p4"},{"id":"week05.5.4.w2","kind":"self","q":"State TWO differences between a liquid and a gas in terms of their particles.","marks":2,"level":2,"lines":3,"scheme":"Liquid particles are close together, gas particles far apart (1). Forces between liquid particles are strong; between gas particles very weak / liquid particles slide past each other, gas particles move freely and fast (1).","points":[{"text":"Liquid particles are close together, gas particles far apart","marks":1},{"text":"Forces between liquid particles are strong; between gas particles very weak / liquid particles slide past each other, gas particles move freely and fast","marks":1}],"section":"warmup","src":"week05.5.3.p2"},{"id":"week05.5.4.w3","kind":"self","q":"Copy and complete: A gas has ……… shape and ……… volume; a liquid has ……… shape and ……… volume.","marks":2,"level":2,"lines":2,"scheme":"Gas: no fixed shape, no fixed volume (1). Liquid: no fixed shape, fixed volume (1).","points":[{"text":"Gas: no fixed shape, no fixed volume","marks":1},{"text":"Liquid: no fixed shape, fixed volume","marks":1}],"section":"warmup","src":"week05.5.3.p3"}],"n":33},{"id":"week05.5.5","kind":"unit","unit":"5.5","title":"Heat Capacity, Specific Heat Capacity and ⟪E=mc\\Delta \\theta⟫","titleText":"Heat Capacity, Specific Heat Capacity and E = mcΔθ","goals":[{"code":"B3.1","text":"Distinguish between heat capacity and specific heat capacity"},{"code":"B3.2","text":"Perform calculations involving ⟪E_{H}=mc\\Delta \\theta⟫"},{"code":"B3.3","text":"Determine the specific heat capacity of metals and liquids using the method of mixtures and the electrical method"}],"codes":["B3.1","B3.2","B3.3"],"words":[{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"learn":{"notes":[{"type":"h","text":"Heat capacity and specific heat capacity (B3.1)"},{"type":"p","text":"Put the same pot on the same flame: 1 kg of water takes much longer to warm than 1 kg of cooking oil, and a full pot takes longer than a half-full pot. How much energy is needed to warm something depends on (1) its **mass**, (2) **what it is made of** and (3) the **temperature rise** you want."},{"type":"def","term":"Heat capacity (C)","text":"the quantity of heat energy needed to raise the temperature of a **whole body** by 1 °C (or 1 K). Unit: **J °C^−1^** or **J K^−1^**."},{"type":"def","term":"Specific heat capacity (c)","text":"the quantity of heat energy needed to raise the temperature of **1 kg** of a substance by 1 °C (or 1 K). Unit: **J kg^−1^ °C^−1^** or **J kg^−1^ K^−1^**."},{"type":"formula","tex":"C=E\\div \\Delta \\theta \\qquad C=m\\times c","where":["⟪C⟫ = heat capacity (J °C^−1^);  m = mass (kg);  c = specific heat capacity (J kg^−1^ °C^−1^)"],"label":"HEAT CAPACITY"},{"type":"table","headers":["","Heat capacity, C","Specific heat capacity, c"],"rows":[["Refers to","A particular object (any mass)","A substance — per kilogram"],["Depends on","Mass AND material","Material only"],["Unit","J °C^−1^ (J K^−1^)","J kg^−1^ °C^−1^ (J kg^−1^ K^−1^)"],["Example","A 2 kg aluminium pot: ⟪C=2\\times 900=1800\\,\\mathrm{J}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","Aluminium: ⟪c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫"]]},{"type":"h","text":"The heat equation (B3.2)"},{"type":"formula","tex":"E_{H}=mc\\Delta \\theta","where":["⟪E_{H}⟫ = heat energy gained or lost (J);  m = mass (kg);  c = specific heat capacity (J kg^−1^ °C^−1^)","⟪\\Delta \\theta⟫ = temperature change = θ~final~ − θ~initial~ (°C or K)","Rearranged:  ⟪c=E\\div (m\\Delta \\theta )⟫;   ⟪m=E\\div (c\\Delta \\theta )⟫;   ⟪\\Delta \\theta =E\\div (mc)⟫"],"label":"THE HEAT EQUATION — LEARN THIS"},{"type":"table","headers":["Substance","c / J kg^−1^ °C^−1^"],"rows":[["Water","4200"],["Ice","2100"],["Cooking oil / paraffin","about 2000–2200"],["Aluminium","900"],["Sand / concrete","about 800"],["Glass","about 670"],["Iron / steel","450"],["Copper","390 (often rounded to 400)"],["Lead","130"]]},{"type":"p","text":"Water has a **very high** specific heat capacity. This explains many everyday effects:"},{"type":"bullets","items":["**Coolant in car engines** — water absorbs a lot of heat for a small temperature rise.","**Hot-water bottles** and the hot water in solar water heaters store a lot of energy and cool slowly.","**Caribbean climate and sea breezes** — land (low c) heats up quickly in the day while the sea stays cooler, so cool air blows in from the sea (sea breeze). At night the sea stays warmer (land breeze). Islands have a mild, steady (maritime) climate.","**Cooking pots** are made of metals with a low c (aluminium, steel) so the pot itself warms up quickly and wastes little energy."]},{"type":"tip","text":"Method for every heat question: (1) write ⟪E=mc\\Delta \\theta⟫; (2) list m, c, Δθ with units — mass in **kg** (divide grams by 1000); (3) substitute; (4) answer with unit J (or kJ)."},{"type":"warn","text":"Using the final temperature instead of the CHANGE in temperature. If water is heated from 25 °C to 80 °C, ⟪\\Delta \\theta =55\\,{}^{\\circ}\\mathrm{C}⟫, not 80 °C.","label":"COMMON MISTAKE"},{"type":"h","text":"Experiment 1: Specific heat capacity of a metal — the electrical method (B3.3)"},{"type":"img","src":"img/week05/shc_electrical","alt":"Figure 5.10 — Electrical method for the specific heat capacity of a metal block","caption":"Figure 5.10 — Electrical method for the specific heat capacity of a metal block","width":5,"w":1167,"h":769},{"type":"p","text":"**Apparatus:** metal block of known mass (e.g. 1.0 kg) with two holes, immersion heater, thermometer, low-voltage d.c. supply, ammeter, voltmeter, stop-watch, lagging (insulation), a little oil."},{"type":"steps","items":["Measure the mass m of the block on a balance.","Put the heater in one hole and the thermometer in the other. Add a drop of **oil** in the thermometer hole for good thermal contact.","Wrap the block in **lagging** (insulation) to reduce heat loss to the surroundings.","Record the starting temperature θ~1~.","Switch on and start the stop-watch. Keep the current steady; record the voltmeter reading V and ammeter reading I.","After a measured time t (e.g. 10 minutes), switch off. Record the **highest** temperature θ~2~ reached (the temperature keeps rising for a short time after switch-off)."]},{"type":"formula","tex":"\\text{Electrical energy supplied }=\\text{ heat gained by block: }VIt=mc\\ (\\theta _{2}-\\theta _{1})\\rightarrow c=VIt\\div (m\\Delta \\theta )","where":["Or with a joulemeter: E = joulemeter reading (J)","Graph method: plot θ against t; gradient ⟪=\\Delta \\theta /\\Delta t⟫, so c = VI ÷ (m × gradient)"],"label":"ELECTRICAL METHOD"},{"type":"p","text":"**Precautions / sources of error:**"},{"type":"bullets","items":["Lag the block to reduce heat loss — heat lost to the surroundings makes the measured c **too high** (more energy seems to be needed than really is).","Oil in the thermometer hole for good thermal contact.","Read the thermometer at eye level to avoid parallax; use the **highest** temperature reached.","Keep the temperature rise moderate (e.g. about 10 °C above room temperature) so the block is not much hotter than the room."]},{"type":"p","text":"**For a liquid:** put a known mass of liquid in a lagged **calorimeter** (metal can) with the heater and a stirrer. Then ⟪VIt=m_{\\text{liquid}}c_{\\text{liquid}}\\Delta \\theta +m_{\\text{can}}c_{\\text{can}}\\Delta \\theta⟫. **Stir** so the temperature is the same throughout."},{"type":"h","text":"Experiment 2: The method of mixtures (B3.3)"},{"type":"img","src":"img/week05/mixtures","alt":"Figure 5.11 — Method of mixtures for the specific heat capacity of a metal","caption":"Figure 5.11 — Method of mixtures for the specific heat capacity of a metal","width":5.2,"w":1111,"h":674},{"type":"steps","items":["Weigh the metal (m~1~). Hang it on a thread in **boiling water** for several minutes so it reaches about 100 °C (θ~1~).","Weigh a calorimeter, add cold water and weigh again to find the mass of water m~2~. Record the water's temperature θ~2~.","**Quickly** transfer the hot metal to the water (to lose little heat on the way, and carry very little boiling water with it).","Stir and record the **highest** temperature reached, θ~3~ (the final, common temperature)."]},{"type":"formula","text":"Heat LOST by hot metal = Heat GAINED by cold water (+ calorimeter)","where":["⟪m_{1}c_{1}\\ (\\theta _{1}-\\theta _{3})=m_{2}c_{\\text{water}}\\ (\\theta _{3}-\\theta _{2})⟫","Solve for c~1~. (Add ⟪m_{\\text{can}}c_{\\text{can}}\\ (\\theta _{3}-\\theta _{2})⟫ on the right if the calorimeter is included.)"],"label":"METHOD OF MIXTURES — CONSERVATION OF ENERGY"},{"type":"remember","text":"In a mixtures question the hot thing cools DOWN to the final temperature and the cold thing warms UP to the same final temperature. Write two separate Δθ values."}],"examples":[{"id":"week05.5.5.e1","title":"Heating water","question":"Calculate the energy needed to heat 2.0 kg of water from 25 °C to 100 °C. ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","steps":[{"label":"Formula","text":"⟪E=mc\\Delta \\theta⟫"},{"label":"Values","text":"⟪m=2.0\\,\\mathrm{kg}⟫, ⟪c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫, ⟪\\Delta \\theta =100-25=75\\,{}^{\\circ}\\mathrm{C}⟫"},{"label":"Substitute","text":"⟪E=2.0\\times 4200\\times 75⟫"},{"label":"Answer","text":"⟪E=630\\,000\\,\\mathrm{J}⟫"}],"answer":"⟪E=6.3\\times 10^{5}\\,\\mathrm{J}\\ (630\\,\\mathrm{kJ})⟫"},{"id":"week05.5.5.e2","title":"How long does the kettle take?","question":"A 2000 W kettle holds 1.5 kg of water at 30 °C. How long does it take to bring the water to 100 °C? Assume no heat is lost.","steps":[{"label":"Energy needed","text":"⟪E=mc\\Delta \\theta =1.5\\times 4200\\times (100-30)=1.5\\times 4200\\times 70=441\\,000\\,\\mathrm{J}⟫"},{"label":"Formula (power)","text":"⟪P=E\\div t\\rightarrow t=E\\div P⟫"},{"label":"Substitute","text":"⟪t=441\\,000\\div 2000=220.5\\,\\mathrm{s}⟫"}],"answer":"⟪t\\approx 221\\,\\mathrm{s}⟫ (about 3.7 minutes)"},{"id":"week05.5.5.e3","title":"Electrical method — using a graph","question":"A 1.0 kg block is heated by a 12 V heater carrying 2.25 A. The graph shows its temperature against time. Use it to find the specific heat capacity of the metal.","img":{"src":"img/week05/block_graph","alt":"A 1.0 kg block is heated by a 12 V heater carrying 2.25 A. The graph shows its temperature against time. Use it to find the specific heat capacity of the metal.","w":1013,"h":614},"steps":[{"label":"Power","text":"⟪P=VI=12\\times 2.25=27\\,\\mathrm{W}⟫"},{"label":"Gradient","text":"From the large triangle: ⟪\\Delta \\theta =12\\,{}^{\\circ}\\mathrm{C}⟫ in ⟪\\Delta t=400\\,\\mathrm{s}⟫  →  gradient ⟪=12\\div 400=0.030\\,{}^{\\circ}\\mathrm{C}\\,\\mathrm{s}^{-1}⟫"},{"label":"Energy in 400 s","text":"⟪E=Pt=27\\times 400=10\\,800\\,\\mathrm{J}⟫"},{"label":"Formula","text":"⟪c=E\\div (m\\Delta \\theta )⟫"},{"label":"Substitute","text":"⟪c=10\\,800\\div (1.0\\times 12)=900⟫"}],"answer":"⟪c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (the block is aluminium)"},{"id":"week05.5.5.e4","title":"Method of mixtures","question":"A 0.50 kg metal block at 100 °C is placed in 0.40 kg of water at 25 °C. The final temperature is 33 °C. Find c for the metal. Ignore the calorimeter and heat losses. ⟪(c_{\\text{water}}=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","steps":[{"label":"Heat gained by water","text":"⟪E=mc\\Delta \\theta =0.40\\times 4200\\times (33-25)=0.40\\times 4200\\times 8=13\\,440\\,\\mathrm{J}⟫"},{"label":"Heat lost by metal","text":"⟪=0.50\\times c\\times (100-33)=33.5c⟫"},{"label":"Heat lost = heat gained","text":"⟪33.5c=13\\,440⟫"},{"label":"Solve","text":"⟪c=13\\,440\\div 33.5=401⟫"}],"answer":"⟪c\\approx 400\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (probably copper)"}]},"tryit":[{"id":"week05.5.5.p1","kind":"self","q":"Define **specific heat capacity** and state its unit.","marks":2,"level":2,"lines":3,"scheme":"The heat energy needed to raise the temperature of 1 kg of a substance by 1 °C (1 K) (1). Unit: J kg⁻¹ °C⁻¹ (or J kg⁻¹ K⁻¹) (1).","points":[{"text":"The heat energy needed to raise the temperature of 1 kg of a substance by 1 °C (1 K)","marks":1},{"text":"Unit: J kg⁻¹ °C⁻¹ (or J kg⁻¹ K⁻¹)","marks":1}],"section":"try","hint":{"text":"Look back at Example 3 (Electrical method — using a graph). Start like this: Power: ⟪P=VI=12\\times 2.25=27\\,\\mathrm{W}⟫","from":3}},{"id":"week05.5.5.p2","kind":"self","q":"State ONE difference between heat capacity and specific heat capacity.","marks":1,"level":1,"lines":2,"scheme":"Heat capacity is for a whole object (depends on mass), specific heat capacity is per kg of the substance (1). [Or units: J °C⁻¹ vs J kg⁻¹ °C⁻¹.]","points":[{"text":"Heat capacity is for a whole object (depends on mass), specific heat capacity is per kg of the substance. [Or units: J °C⁻¹ vs J kg⁻¹ °C⁻¹.]","marks":1}],"section":"try","hint":{"text":"Look back at Example 3 (Electrical method — using a graph). Start like this: Power: ⟪P=VI=12\\times 2.25=27\\,\\mathrm{W}⟫","from":3}}],"practice":[{"id":"week05.5.5.p3","kind":"num","q":"Calculate the heat needed to raise the temperature of 0.50 kg of water from 20 °C to 80 °C. ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪E=mc\\Delta \\theta =0.50\\times 4200\\times 60⟫ (1) ⟪=126\\,000\\,\\mathrm{J}\\ (1.26\\times 10^{5}\\,\\mathrm{J})⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta =0.50\\times 4200\\times 60⟫","marks":1},{"text":"⟪=126\\,000\\,\\mathrm{J}\\ (1.26\\times 10^{5}\\,\\mathrm{J})⟫","marks":1}],"num":{"value":126000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (Heating water). Start like this: Formula: ⟪E=mc\\Delta \\theta⟫","from":1}},{"id":"week05.5.5.p4","kind":"num","q":"How much energy is needed to warm a 2.0 kg aluminium pot from 25 °C to 75 °C? ⟪(c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪E=2.0\\times 900\\times 50⟫ (1) ⟪=90\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=2.0\\times 900\\times 50⟫","marks":1},{"text":"⟪=90\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":90000,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 1 (Heating water). Start like this: Formula: ⟪E=mc\\Delta \\theta⟫","from":1}},{"id":"week05.5.5.p5","kind":"self","q":"A 0.30 kg copper block has ⟪c=390\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫. (a) Calculate its heat capacity. (b) How much energy raises its temperature by 20 °C?","marks":3,"level":2,"lines":4,"scheme":"(a) ⟪C=mc=0.30\\times 390=117\\,\\mathrm{J}\\,{}^{\\circ}\\mathrm{C}^{-1}\\ (1+1\\,\\mathrm{unit})⟫. (b) ⟪E=C\\Delta \\theta =117\\times 20=2340\\,\\mathrm{J}⟫ (1).","points":[{"text":"(a) ⟪C=mc=0.30\\times 390=117\\,\\mathrm{J}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":2},{"text":"(b) ⟪E=C\\Delta \\theta =117\\times 20=2340\\,\\mathrm{J}⟫","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Electrical method — using a graph). Start like this: Power: ⟪P=VI=12\\times 2.25=27\\,\\mathrm{W}⟫","from":3}},{"id":"week05.5.5.p6","kind":"num","q":"18 000 J of heat raises the temperature of 0.40 kg of a liquid by 25 °C. Calculate the specific heat capacity of the liquid.","marks":2,"level":2,"lines":3,"scheme":"⟪c=E\\div (m\\Delta \\theta )=18\\,000\\div (0.40\\times 25)⟫ (1) ⟪=1800\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1).","points":[{"text":"⟪c=E\\div (m\\Delta \\theta )=18\\,000\\div (0.40\\times 25)⟫","marks":1},{"text":"⟪=1800\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1}],"num":{"value":1800,"sf":2,"unit":"J kg^−1^ °C^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}"},"section":"practice","hint":{"text":"Look back at Example 3 (Electrical method — using a graph). Start like this: Power: ⟪P=VI=12\\times 2.25=27\\,\\mathrm{W}⟫","from":3}},{"id":"week05.5.5.p7","kind":"num","q":"A 2.2 kW kettle contains 1.2 kg of water at 28 °C. Calculate the time to heat it to 100 °C, assuming no heat losses.","marks":4,"level":3,"lines":5,"scheme":"⟪E=mc\\Delta \\theta =1.2\\times 4200\\times 72⟫ (1) ⟪=362\\,880\\,\\mathrm{J}⟫ (1). ⟪t=E\\div P=362\\,880\\div 2200⟫ (1) ⟪=165\\,\\mathrm{s}⟫ (accept 164.9 s) (1).","points":[{"text":"⟪E=mc\\Delta \\theta =1.2\\times 4200\\times 72⟫","marks":1},{"text":"⟪=362\\,880\\,\\mathrm{J}⟫","marks":1},{"text":"⟪t=E\\div P=362\\,880\\div 2200⟫","marks":1},{"text":"⟪=165\\,\\mathrm{s}⟫ (accept 164.9 s)","marks":1}],"num":{"value":165,"sf":3,"unit":"s","unitTex":"\\mathrm{s}"},"section":"practice","hint":{"text":"Look back at Example 1 (Heating water). Start like this: Formula: ⟪E=mc\\Delta \\theta⟫","from":1}},{"id":"week05.5.5.p8","kind":"self","q":"Explain why, on a sunny Caribbean day, the sand on the beach becomes much hotter than the sea.","marks":2,"level":2,"lines":3,"scheme":"Sand has a much lower specific heat capacity than water (1), so the same energy from the Sun gives the sand a much bigger temperature rise (1). [Also accept: heat is spread through a large depth of moving water.]","points":[{"text":"Sand has a much lower specific heat capacity than water","marks":1},{"text":"so the same energy from the Sun gives the sand a much bigger temperature rise. [Also accept: heat is spread through a large depth of moving water.]","marks":1}],"section":"practice"},{"id":"week05.5.5.p9","kind":"self","q":"In the electrical method, a 1.5 kg iron block is heated by a 12 V heater carrying 3.0 A for 10 minutes. Its temperature rises from 21.0 °C to 52.0 °C. (a) Calculate the energy supplied. (b) Calculate c for iron. (c) The accepted value is 450 J kg^−1^ °C^−1^. Explain why the experimental value is higher.","marks":6,"level":3,"lines":7,"scheme":"(a) ⟪E=VIt=12\\times 3.0\\times 600⟫ (1) ⟪=21\\,600\\,\\mathrm{J}⟫ (1). (b) ⟪c=21\\,600\\div (1.5\\times 31.0)⟫ (1) ⟪=465\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1). (c) Some heat is lost to the surroundings (1), so less energy actually heats the block; the calculation assumes all 21 600 J went into the block, giving c too large (1).","points":[{"text":"(a) ⟪E=VIt=12\\times 3.0\\times 600⟫","marks":1},{"text":"⟪=21\\,600\\,\\mathrm{J}⟫","marks":1},{"text":"(b) ⟪c=21\\,600\\div (1.5\\times 31.0)⟫","marks":1},{"text":"⟪=465\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1},{"text":"(c) Some heat is lost to the surroundings","marks":1},{"text":"so less energy actually heats the block; the calculation assumes all 21 600 J went into the block, giving c too large","marks":1}],"section":"practice","hint":{"text":"Look back at Example 1 (Heating water). Start like this: Formula: ⟪E=mc\\Delta \\theta⟫","from":1}}],"exit":[{"id":"week05.5.5.p10","kind":"num","q":"A 0.10 kg piece of metal at 100 °C is dropped into 0.20 kg of water at 20.0 °C. The final temperature is 24.0 °C. Calculate c for the metal (ignore the container).","marks":4,"level":3,"lines":5,"scheme":"Heat gained by water ⟪=0.20\\times 4200\\times 4.0=3360\\,\\mathrm{J}⟫ (1). Heat lost by metal ⟪=0.10\\times c\\times 76=7.6c⟫ (1). ⟪7.6c=3360⟫ (1) → ⟪c=442\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1).","points":[{"text":"Heat gained by water ⟪=0.20\\times 4200\\times 4.0=3360\\,\\mathrm{J}⟫","marks":1},{"text":"Heat lost by metal ⟪=0.10\\times c\\times 76=7.6c⟫","marks":1},{"text":"⟪7.6c=3360⟫","marks":1},{"text":"→ ⟪c=442\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1}],"num":{"value":442,"sf":3,"unit":"J kg^−1^ °C^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}"},"section":"exit"},{"id":"week05.5.5.p11","kind":"num","q":"0.30 kg of water at 80 °C is mixed with 0.20 kg of water at 20 °C. Find the final temperature (no heat losses).","marks":3,"level":2,"lines":4,"scheme":"Heat lost = heat gained: ⟪0.30\\times 4200\\times (80-T)=0.20\\times 4200\\times (T-20)⟫ (1) → ⟪24-0.30\\mathrm{T}=0.20\\mathrm{T}-4⟫ (1) → ⟪T=28\\div 0.50=56\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"Heat lost = heat gained: ⟪0.30\\times 4200\\times (80-T)=0.20\\times 4200\\times (T-20)⟫","marks":1},{"text":"→ ⟪24-0.30\\mathrm{T}=0.20\\mathrm{T}-4⟫","marks":1},{"text":"→ ⟪T=28\\div 0.50=56\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"num":{"value":56,"sf":2,"unit":"°C","unitTex":"{}^{\\circ}\\mathrm{C}"},"section":"exit"}],"warmup":[{"id":"week05.5.5.w1","kind":"self","q":"Why are overhead power cables hung slack instead of tight?","marks":2,"level":2,"lines":3,"scheme":"In cold weather the cables contract (1); if they were tight they could snap / pull down the poles (1).","points":[{"text":"In cold weather the cables contract","marks":1},{"text":"if they were tight they could snap / pull down the poles","marks":1}],"section":"warmup","src":"week05.5.4.p3"},{"id":"week05.5.5.w2","kind":"self","q":"Explain, in terms of particles, why a metal rod gets longer when it is heated.","marks":2,"level":2,"lines":3,"scheme":"Particles gain kinetic energy and vibrate more vigorously (1); the average distance between them increases, so the rod expands (1).","points":[{"text":"Particles gain kinetic energy and vibrate more vigorously","marks":1},{"text":"the average distance between them increases, so the rod expands","marks":1}],"section":"warmup","src":"week05.5.4.p1"},{"id":"week05.5.5.w3","kind":"self","q":"A bimetallic strip is made of brass and invar. Brass expands much more than invar. Draw/describe the shape of the strip after heating and state which metal is on the outside.","marks":2,"level":2,"lines":3,"scheme":"The strip bends/curves (1) with brass on the outside of the curve (1).","points":[{"text":"The strip bends/curves","marks":1},{"text":"with brass on the outside of the curve","marks":1}],"section":"warmup","src":"week05.5.4.p5"}],"n":34},{"id":"week05.5.6","kind":"unit","unit":"5.6","title":"Latent Heat, Cooling Curves, Evaporation and Boiling","titleText":"Latent Heat, Cooling Curves, Evaporation and Boiling","goals":[{"code":"B3.4","text":"Demonstrate that the temperature of a substance remains constant during a change of phase (cooling curve)"},{"code":"B3.5","text":"Perform calculations involving ⟪E_{H}=ml⟫"},{"code":"B3.6","text":"Determine the specific latent heat of fusion and of vaporisation"},{"code":"B3.7","text":"Distinguish between evaporation and boiling"}],"codes":["B3.4","B3.5","B3.6","B3.7"],"words":[{"term":"Heat","def":"Energy transferred from a hotter to a colder body because of a temperature difference (J)."},{"term":"Temperature","def":"Degree of hotness of a body; related to the average kinetic energy of its particles (°C or K)."},{"term":"Latent heat","def":"Heat absorbed or released during a change of state at constant temperature."},{"term":"Specific latent heat of fusion","def":"Heat needed to change 1 kg of solid to liquid without a change in temperature (J kg^−1^)."},{"term":"Specific latent heat of vaporisation","def":"Heat needed to change 1 kg of liquid to vapour without a change in temperature (J kg^−1^)."},{"term":"Evaporation","def":"Change from liquid to vapour at the surface, at any temperature; causes cooling."},{"term":"Boiling","def":"Change from liquid to vapour throughout the liquid, at a fixed temperature (boiling point)."}],"learn":{"notes":[{"type":"h","text":"Latent heat: the \"hidden\" heat"},{"type":"p","text":"If you keep heating ice in a beaker, the thermometer stays at **0 °C** until all the ice has melted, even though heat is going in all the time. The same happens at **100 °C** while water boils. The energy is still being absorbed, but it is \"hidden\" (latent) — it does not raise the temperature."},{"type":"def","term":"Latent heat","text":"the heat energy absorbed or released when a substance changes state (phase) **without any change in temperature**."},{"type":"def","term":"Specific latent heat of fusion (l~f~)","text":"the quantity of heat energy needed to change **1 kg** of a substance from **solid to liquid** without a change in temperature. Unit: J kg^−1^."},{"type":"def","term":"Specific latent heat of vaporisation (l~v~)","text":"the quantity of heat energy needed to change **1 kg** of a substance from **liquid to gas (vapour)** without a change in temperature. Unit: J kg^−1^."},{"type":"formula","tex":"E_{H}=ml","where":["⟪E_{H}⟫ = heat energy (J);  m = mass that changes state (kg);  l = specific latent heat (J kg^−1^)","Ice: ⟪l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫ (some papers use 3.3 or ⟪3.36\\times 10^{5}⟫ — always use the value given)","Water: ⟪l_{v}=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫ (often given as ⟪2.3\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫)"],"label":"LATENT HEAT EQUATION"},{"type":"h","text":"Why does the temperature stay constant? (B3.4)"},{"type":"bullets","items":["Temperature depends on the **kinetic energy** of the particles.","During melting or boiling, the energy supplied is used to **break the bonds** (overcome the forces of attraction) between particles — it increases their **potential energy**, not their kinetic energy.","Since the average KE does not change, the **temperature does not change** until the change of state is complete.","When a substance freezes or condenses, the same latent heat is **released** — so a freezing liquid stays at its freezing point while it gives out heat."]},{"type":"h","text":"The heating curve of water"},{"type":"img","src":"img/week05/heating_curve","alt":"Figure 5.12 — Heating curve: ice at −20 °C heated steadily until it becomes steam","caption":"Figure 5.12 — Heating curve: ice at −20 °C heated steadily until it becomes steam","width":4.8,"w":1134,"h":694},{"type":"table","headers":["Section","State","What the energy does","Equation"],"rows":[["A","Solid (ice) warming","Increases KE → temperature rises","⟪E=mc_{\\text{ice}}\\Delta \\theta⟫"],["B","Melting at 0 °C: solid + liquid","Breaks bonds; temperature constant","⟪E=ml_{f}⟫"],["C","Liquid (water) warming","Increases KE → temperature rises","⟪E=mc_{\\text{water}}\\Delta \\theta⟫"],["D","Boiling at 100 °C: liquid + gas","Separates molecules completely; temperature constant","⟪E=ml_{v}⟫"],["E","Gas (steam) warming","Increases KE → temperature rises","⟪E=mc_{\\text{steam}}\\Delta \\theta⟫"]]},{"type":"tip","text":"Section D is much LONGER than section B because ⟪l_{v}\\ (2.26\\times 10^{6})⟫ is almost 7 times ⟪l_{f}\\ (3.4\\times 10^{5})⟫: it takes far more energy to pull molecules completely apart than to loosen them. Section A is steeper than C because ice has a smaller specific heat capacity than water."},{"type":"h","text":"Experiment: a cooling curve shows constant temperature during a change of phase (B3.4)"},{"type":"img","src":"img/week05/cooling_curve","alt":"Figure 5.13 — Cooling curve for a substance (e.g. stearic acid or a wax) as it changes from liquid to solid","caption":"Figure 5.13 — Cooling curve for a substance (e.g. stearic acid or a wax) as it changes from liquid to solid","width":4.6,"w":1094,"h":654},{"type":"p","text":"**Apparatus:** boiling tube of stearic acid (or naphthalene/wax), beaker of hot water (water bath), thermometer (0–110 °C), stop-watch, clamp and stand."},{"type":"steps","items":["Heat the boiling tube in the water bath until the solid has **completely melted** and is at about 90 °C.","Remove the tube from the bath, clamp it in air, with the thermometer in the liquid.","Record the temperature **every 30 s (or every minute)** and note the state (liquid / solid forming / solid). Stir gently with the thermometer while it is still liquid.","Continue until the substance is completely solid and has cooled to about 40 °C.","Plot a graph of temperature (y-axis) against time (x-axis)."]},{"type":"p","text":"**Results and conclusion:** the curve falls, then has a **flat (horizontal) section** while the liquid freezes, then falls again. The temperature of the flat part is the **freezing point = melting point** of the substance. The temperature stays constant because the latent heat released as the particles bond together balances the heat lost to the surroundings."},{"type":"p","text":"**Precautions:** heat with a water bath, not a direct flame (stearic acid/naphthalene are flammable); ensure the thermometer bulb is fully in the substance; read the thermometer at eye level; do not try to pull the thermometer out of the solid."},{"type":"h","text":"Experiment: specific latent heat of fusion of ice (B3.6)"},{"type":"img","src":"img/week05/latent_fusion","alt":"Figure 5.14 — Two funnels of crushed ice: one with an immersion heater (experiment), one without (control)","caption":"Figure 5.14 — Two funnels of crushed ice: one with an immersion heater (experiment), one without (control)","width":5.2,"w":1008,"h":691},{"type":"steps","items":["Set up **two** identical funnels packed with crushed ice at 0 °C, each with a beaker underneath. Put an immersion heater in one funnel only.","When water is dripping steadily from both, place **empty, weighed beakers** under the funnels and switch on the heater and start the clock at the same time.","After a measured time t, switch off and weigh both beakers of melt water: m~exp~ (with heater) and m~control~ (without heater).","Energy from heater ⟪E=VIt⟫ (or the joulemeter reading, or ⟪P\\times t⟫).","Mass melted by the heater alone: ⟪m=m_{\\text{exp}}-m_{\\text{control}}⟫."]},{"type":"formula","tex":"l_{f}=E\\div (m_{\\text{exp}}-m_{\\text{control}})=VIt\\div (m_{\\text{exp}}-m_{\\text{control}})","where":["The **control** funnel measures ice melted by heat from the **room**. Subtracting it leaves only the ice melted by the heater."],"label":"FUSION EXPERIMENT"},{"type":"p","text":"**Precautions:** use **crushed** ice (good contact with the heater); ice should be **melting** (at 0 °C, not colder); the heater must be **completely covered** by ice; drain the ice well before starting."},{"type":"h","text":"Experiment: specific latent heat of vaporisation of water (B3.6)"},{"type":"img","src":"img/week05/latent_vap","alt":"Figure 5.15 — Water boiled by an immersion heater in a lagged beaker on a top-pan balance","caption":"Figure 5.15 — Water boiled by an immersion heater in a lagged beaker on a top-pan balance","width":4,"w":903,"h":734},{"type":"steps","items":["Place a lagged beaker of water with an immersion heater on a top-pan balance. Heat until the water is **boiling steadily**.","Record the balance reading m~1~ and start the clock.","Keep the water boiling for a measured time t (e.g. 10 minutes), then record the new reading m~2~.","Mass of water boiled away ⟪m=m_{1}-m_{2}⟫.  Energy supplied ⟪E=Pt⟫ (or VIt)."]},{"type":"formula","tex":"l_{v}=Pt\\div (m_{1}-m_{2})","where":["Heat losses make the calculated value too HIGH (some of the heater energy did not go into boiling)."],"label":"VAPORISATION EXPERIMENT"},{"type":"p","text":"**Precautions:** start timing only when the water is boiling steadily (so all the energy goes into vaporising, not warming); lag the beaker; keep the heater fully immersed; avoid splashing (water lost as droplets would make l~v~ too low)."},{"type":"h","text":"Evaporation and boiling (B3.7)"},{"type":"def","term":"Evaporation","text":"the change from liquid to vapour that takes place at the **surface** of a liquid at **any temperature**."},{"type":"def","term":"Boiling","text":"the change from liquid to vapour that takes place **throughout** the liquid (bubbles form inside it) at a **fixed temperature**, the boiling point."},{"type":"table","headers":["Evaporation","Boiling"],"rows":[["Happens at ANY temperature","Happens at ONE fixed temperature (boiling point) for a given pressure"],["Only at the SURFACE","THROUGHOUT the liquid — bubbles of vapour form"],["Slow, quiet; no bubbles","Fast, with bubbles"],["Causes COOLING of the liquid","Temperature stays CONSTANT (heat must be supplied)"],["Rate depends on temperature, surface area, draught, humidity","Boiling point depends on pressure and impurities"],["Energy comes from the liquid itself / surroundings","Energy must be supplied by a heat source"]]},{"type":"h","text":"Why evaporation causes cooling"},{"type":"bullets","items":["Molecules in a liquid move at different speeds.","The **fastest** (most energetic) molecules near the surface can escape.","The molecules left behind have a **lower average kinetic energy**, so the **temperature of the liquid falls**.","The liquid then takes heat from its surroundings (e.g. your skin), which cools them."]},{"type":"table","headers":["Factor","Effect on rate of evaporation"],"rows":[["Higher temperature","Faster — more molecules have enough energy to escape"],["Larger surface area","Faster — more molecules at the surface"],["Wind / draught","Faster — blows vapour molecules away before they return to the liquid"],["Lower humidity (drier air)","Faster — air can hold more vapour"],["Volatile liquid (e.g. alcohol, ether)","Faster — weaker forces between molecules"]]},{"type":"p","text":"**Applications of cooling by evaporation:** sweating cools the body (sweat evaporates, taking latent heat from the skin); clay water-jars (\"goblets\") keep water cool as water seeps through and evaporates from the surface; spirit on the skin feels cold; a fan cools you by speeding up evaporation of sweat; the **refrigerator** works by a liquid (refrigerant) evaporating in pipes inside the fridge, taking latent heat from the food."},{"type":"warn","text":"Steam at 100 °C causes a much worse burn than boiling water at 100 °C. When steam condenses on skin it first **releases its latent heat of vaporisation** (⟪2.26\\times 10^{6}\\,\\mathrm{J}⟫ for every kg), and THEN the hot water cools. Students who say \"steam is hotter\" lose the mark.","label":"EXAM FAVOURITE"}],"examples":[{"id":"week05.5.6.e1","title":"Melting ice","question":"How much energy is needed to melt 0.50 kg of ice at 0 °C? ⟪(l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","steps":[{"label":"Formula","text":"⟪E=ml⟫"},{"label":"Substitute","text":"⟪E=0.50\\times 3.4\\times 10^{5}⟫"},{"label":"Answer","text":"⟪E=1.7\\times 10^{5}\\,\\mathrm{J}⟫"}],"answer":"⟪E=1.7\\times 10^{5}\\,\\mathrm{J}\\ (170\\,000\\,\\mathrm{J})⟫"},{"id":"week05.5.6.e2","title":"Several stages: ice at −10 °C to water at 20 °C","question":"Calculate the total energy needed to change 0.20 kg of ice at −10 °C into water at 20 °C. (⟪c_{\\text{ice}}=2100⟫, ⟪c_{\\text{water}}=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫; ⟪l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫)","steps":[{"label":"Stage 1: warm ice ⟪-10\\rightarrow 0\\,{}^{\\circ}\\mathrm{C}⟫","text":"⟪E_{1}=mc\\Delta \\theta =0.20\\times 2100\\times 10=4200\\,\\mathrm{J}⟫"},{"label":"Stage 2: melt at 0 °C","text":"⟪E_{2}=ml_{f}=0.20\\times 3.4\\times 10^{5}=68\\,000\\,\\mathrm{J}⟫"},{"label":"Stage 3: warm water 0 → 20 °C","text":"⟪E_{3}=mc\\Delta \\theta =0.20\\times 4200\\times 20=16\\,800\\,\\mathrm{J}⟫"},{"label":"Total","text":"⟪E=4200+68\\,000+16\\,800=89\\,000\\,\\mathrm{J}⟫"}],"answer":"⟪E=8.9\\times 10^{4}\\,\\mathrm{J}⟫"},{"id":"week05.5.6.e3","title":"Latent heat of fusion experiment","question":"In the two-funnel experiment a 50 W heater runs for 5.0 minutes. The beaker under the heated funnel collects 0.062 kg of water; the control beaker collects 0.018 kg. Calculate l~f~ for ice.","steps":[{"label":"Energy from heater","text":"⟪E=Pt=50\\times 300=15\\,000\\,\\mathrm{J}⟫"},{"label":"Mass melted by heater","text":"⟪m=0.062-0.018=0.044\\,\\mathrm{kg}⟫"},{"label":"Formula","text":"⟪l_{f}=E\\div m⟫"},{"label":"Substitute","text":"⟪l_{f}=15\\,000\\div 0.044=340\\,909⟫"}],"answer":"⟪l_{f}\\approx 3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫"},{"id":"week05.5.6.e4","title":"Latent heat of vaporisation experiment","question":"A 120 W heater keeps water boiling for 10 minutes. The balance reading falls from 245.6 g to 213.6 g. Calculate l~v~ for water.","steps":[{"label":"Energy","text":"⟪E=Pt=120\\times 600=72\\,000\\,\\mathrm{J}⟫"},{"label":"Mass boiled away","text":"⟪m=245.6-213.6=32.0\\,\\mathrm{g}=0.0320\\,\\mathrm{kg}⟫"},{"label":"Formula","text":"⟪l_{v}=E\\div m⟫"},{"label":"Substitute","text":"⟪l_{v}=72\\,000\\div 0.0320=2\\,250\\,000⟫"}],"answer":"⟪l_{v}=2.25\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫"}]},"tryit":[{"id":"week05.5.6.p1","kind":"self","q":"Define **specific latent heat of vaporisation**.","marks":2,"level":2,"lines":3,"scheme":"The heat energy needed to change 1 kg of a liquid into vapour (1) without a change in temperature (1).","points":[{"text":"The heat energy needed to change 1 kg of a liquid into vapour","marks":1},{"text":"without a change in temperature","marks":1}],"section":"try","hint":{"text":"Look back at Example 4 (Latent heat of vaporisation experiment). Start like this: Energy: ⟪E=Pt=120\\times 600=72\\,000\\,\\mathrm{J}⟫","from":4}},{"id":"week05.5.6.p2","kind":"self","q":"Explain, in terms of molecules, why the temperature of melting ice stays at 0 °C even though it is being heated.","marks":3,"level":2,"lines":4,"scheme":"Energy breaks bonds between molecules (1); it increases their PE (1), not their KE, so the temperature stays constant (1).","points":[{"text":"Energy breaks bonds between molecules","marks":1},{"text":"it increases their PE","marks":1},{"text":"not their KE, so the temperature stays constant","marks":1}],"section":"try"}],"practice":[{"id":"week05.5.6.p3","kind":"num","q":"Calculate the energy needed to boil away 0.25 kg of water already at 100 °C. ⟪(l_{v}=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪E=ml=0.25\\times 2.26\\times 10^{6}⟫ (1) ⟪=5.65\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=ml=0.25\\times 2.26\\times 10^{6}⟫","marks":1},{"text":"⟪=5.65\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":565000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (Several stages: ice at −10 °C to water at 20 °C). Start like this: Stage 1: warm ice ⟪-10\\rightarrow 0\\,{}^{\\circ}\\mathrm{C}⟫: ⟪E_{1}=mc\\Delta \\theta =0.20\\times 2100\\times 10=4200\\,\\mathrm{J}⟫","from":2}},{"id":"week05.5.6.p4","kind":"num","q":"What mass of ice at 0 °C is melted by 50 000 J of heat? ⟪(l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪m=E\\div l=50\\,000\\div 3.4\\times 10^{5}⟫ (1) ⟪=0.147\\,\\mathrm{kg}\\ (147\\,\\mathrm{g})⟫ (1).","points":[{"text":"⟪m=E\\div l=50\\,000\\div 3.4\\times 10^{5}⟫","marks":1},{"text":"⟪=0.147\\,\\mathrm{kg}\\ (147\\,\\mathrm{g})⟫","marks":1}],"num":{"value":0.147,"sf":3,"unit":"kg","unitTex":"\\mathrm{kg}","alt":[147]},"section":"practice","hint":{"text":"Look back at Example 3 (Latent heat of fusion experiment). Start like this: Energy from heater: ⟪E=Pt=50\\times 300=15\\,000\\,\\mathrm{J}⟫","from":3}},{"id":"week05.5.6.p5","kind":"num","q":"A 3.0 kW kettle has been left on with 0.40 kg of boiling water inside. How long will it take to boil all the water away? ⟪(l_{v}=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","marks":3,"level":2,"lines":4,"scheme":"⟪E=ml=0.40\\times 2.26\\times 10^{6}=9.04\\times 10^{5}\\,\\mathrm{J}⟫ (1). ⟪t=E\\div P=904\\,000\\div 3000⟫ (1) ⟪=301\\,\\mathrm{s}⟫ (about 5.0 min) (1).","points":[{"text":"⟪E=ml=0.40\\times 2.26\\times 10^{6}=9.04\\times 10^{5}\\,\\mathrm{J}⟫","marks":1},{"text":"⟪t=E\\div P=904\\,000\\div 3000⟫","marks":1},{"text":"⟪=301\\,\\mathrm{s}⟫ (about 5.0 min)","marks":1}],"num":{"value":301,"sf":3,"unit":"s","unitTex":"\\mathrm{s}"},"conf":"low","section":"practice"},{"id":"week05.5.6.p6","kind":"num","q":"Calculate the total energy needed to change 0.10 kg of water at 30 °C into steam at 100 °C. (⟪c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫; ⟪l_{v}=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫)","marks":4,"level":3,"lines":5,"scheme":"Warm: ⟪0.10\\times 4200\\times 70=29\\,400\\,\\mathrm{J}⟫ (1). Boil: ⟪0.10\\times 2.26\\times 10^{6}=226\\,000\\,\\mathrm{J}⟫ (1). Total ⟪=29\\,400+226\\,000⟫ (1) ⟪=2.55\\times 10^{5}\\,\\mathrm{J}⟫ (1).","points":[{"text":"Warm: ⟪0.10\\times 4200\\times 70=29\\,400\\,\\mathrm{J}⟫","marks":1},{"text":"Boil: ⟪0.10\\times 2.26\\times 10^{6}=226\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"Total ⟪=29\\,400+226\\,000⟫","marks":1},{"text":"⟪=2.55\\times 10^{5}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":255000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"practice","hint":{"text":"Look back at Example 2 (Several stages: ice at −10 °C to water at 20 °C). Start like this: Stage 1: warm ice ⟪-10\\rightarrow 0\\,{}^{\\circ}\\mathrm{C}⟫: ⟪E_{1}=mc\\Delta \\theta =0.20\\times 2100\\times 10=4200\\,\\mathrm{J}⟫","from":2}},{"id":"week05.5.6.p7","kind":"self","q":"In the fusion experiment, why is a second (control) funnel with no heater used?","marks":2,"level":2,"lines":3,"scheme":"Some ice melts due to heat from the room (1); the control measures this so it can be subtracted, leaving the mass melted by the heater only (1).","points":[{"text":"Some ice melts due to heat from the room","marks":1},{"text":"the control measures this so it can be subtracted, leaving the mass melted by the heater only","marks":1}],"section":"practice","hint":{"text":"Look back at Example 3 (Latent heat of fusion experiment). Start like this: Energy from heater: ⟪E=Pt=50\\times 300=15\\,000\\,\\mathrm{J}⟫","from":3}},{"id":"week05.5.6.p8","kind":"self","q":"State THREE differences between evaporation and boiling.","marks":3,"level":2,"lines":4,"scheme":"Any three (1 each): any temperature vs fixed temperature; surface only vs throughout; no bubbles vs bubbles; causes cooling vs constant temperature.","points":[{"text":"Any three (1 each): any temperature vs fixed temperature; surface only vs throughout; no bubbles vs bubbles; causes cooling vs constant temperature.","marks":3,"each":true}],"section":"practice"},{"id":"week05.5.6.p9","kind":"self","q":"Explain why you feel cool after a swim even on a warm day, especially in a breeze.","marks":3,"level":2,"lines":4,"scheme":"Water on the skin evaporates (1); the fastest molecules escape, taking latent heat from the skin (1); wind removes vapour → faster evaporation → more cooling (1).","points":[{"text":"Water on the skin evaporates","marks":1},{"text":"the fastest molecules escape, taking latent heat from the skin","marks":1},{"text":"wind removes vapour → faster evaporation → more cooling","marks":1}],"section":"practice"},{"id":"week05.5.6.p10","kind":"self","q":"Explain why a burn from steam at 100 °C is more serious than a burn from the same mass of water at 100 °C.","marks":2,"level":2,"lines":3,"scheme":"Condensing steam releases its large latent heat of vaporisation (1) as well as the heat given out as the water then cools — more energy to the skin (1).","points":[{"text":"Condensing steam releases its large latent heat of vaporisation","marks":1},{"text":"as well as the heat given out as the water then cools — more energy to the skin","marks":1}],"section":"practice"}],"exit":[{"id":"week05.5.6.p11","kind":"self","q":"On a cooling curve, what does the horizontal section represent? What is the temperature of this section called?","marks":2,"level":2,"lines":3,"scheme":"Change of state (freezing) at constant temperature as latent heat is released (1). Freezing point (= melting point) (1).","points":[{"text":"Change of state (freezing) at constant temperature as latent heat is released","marks":1},{"text":"Freezing point (= melting point)","marks":1}],"section":"exit"},{"id":"week05.5.6.p12","kind":"self","q":"Describe an experiment to show that the temperature of a substance stays constant while it freezes. Include the apparatus, the readings taken and how the result is shown.","marks":5,"level":3,"lines":6,"scheme":"Melt stearic acid/naphthalene in a boiling tube in a hot-water bath (1); remove tube and place thermometer in the liquid (1); record temperature at regular intervals, e.g. every 30 s, until solid and cooled (1); plot temperature against time — a cooling curve (1); the horizontal section shows the temperature is constant while freezing (1).","points":[{"text":"Melt stearic acid/naphthalene in a boiling tube in a hot-water bath","marks":1},{"text":"remove tube and place thermometer in the liquid","marks":1},{"text":"record temperature at regular intervals, e.g. every 30 s, until solid and cooled","marks":1},{"text":"plot temperature against time — a cooling curve","marks":1},{"text":"the horizontal section shows the temperature is constant while freezing","marks":1}],"section":"exit"}],"warmup":[{"id":"week05.5.6.w1","kind":"self","q":"Define **specific heat capacity** and state its unit.","marks":2,"level":2,"lines":3,"scheme":"The heat energy needed to raise the temperature of 1 kg of a substance by 1 °C (1 K) (1). Unit: J kg⁻¹ °C⁻¹ (or J kg⁻¹ K⁻¹) (1).","points":[{"text":"The heat energy needed to raise the temperature of 1 kg of a substance by 1 °C (1 K)","marks":1},{"text":"Unit: J kg⁻¹ °C⁻¹ (or J kg⁻¹ K⁻¹)","marks":1}],"section":"warmup","src":"week05.5.5.p1"},{"id":"week05.5.6.w2","kind":"num","q":"Calculate the heat needed to raise the temperature of 0.50 kg of water from 20 °C to 80 °C. ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪E=mc\\Delta \\theta =0.50\\times 4200\\times 60⟫ (1) ⟪=126\\,000\\,\\mathrm{J}\\ (1.26\\times 10^{5}\\,\\mathrm{J})⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta =0.50\\times 4200\\times 60⟫","marks":1},{"text":"⟪=126\\,000\\,\\mathrm{J}\\ (1.26\\times 10^{5}\\,\\mathrm{J})⟫","marks":1}],"num":{"value":126000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week05.5.5.p3"},{"id":"week05.5.6.w3","kind":"num","q":"How much energy is needed to warm a 2.0 kg aluminium pot from 25 °C to 75 °C? ⟪(c=900\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"⟪E=2.0\\times 900\\times 50⟫ (1) ⟪=90\\,000\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=2.0\\times 900\\times 50⟫","marks":1},{"text":"⟪=90\\,000\\,\\mathrm{J}⟫","marks":1}],"num":{"value":90000,"sf":1,"unit":"J","unitTex":"\\mathrm{J}"},"section":"warmup","src":"week05.5.5.p4"}],"n":35},{"id":"week05.check","kind":"check","title":"Book check","titleText":"Book check","check":true,"watchOut":["Confusing heat and temperature. Temperature is \"how hot\" (average KE of particles, °C); heat is energy transferred (J).","Using the final temperature instead of the temperature CHANGE in ⟪E=mc\\Delta \\theta⟫ (heated from 20 °C to ⟪70\\,{}^{\\circ}\\mathrm{C}\\rightarrow \\Delta \\theta =50\\,{}^{\\circ}\\mathrm{C}⟫).","Leaving mass in grams. ⟪250\\,\\mathrm{g}=0.250\\,\\mathrm{kg}⟫ before substituting.","Leaving time in minutes when using ⟪E=Pt⟫ or ⟪E=VIt⟫. ⟪5\\,\\mathrm{min}=300\\,\\mathrm{s}⟫.","Saying \"steam is hotter than boiling water\" to explain worse steam burns. Both are at 100 °C — steam releases LATENT HEAT as it condenses.","Saying particles expand when a substance is heated. The SPACES between particles increase; the particles stay the same size.","In a method-of-mixtures question, using one Δθ for both substances. The hot object's ⟪\\Delta \\theta =(\\theta _{\\text{hot}}-\\theta _{\\text{final}})⟫; the cold water's ⟪\\Delta \\theta =(\\theta _{\\text{final}}-\\theta _{\\text{cold}})⟫.","Saying temperature stays constant during melting because \"the heat is lost\". The heat is used to break bonds (increase PE), not to increase KE.","Mixing up evaporation and boiling: evaporation is at the SURFACE at ANY temperature and causes cooling.","Forgetting why a control funnel is used in the latent heat of fusion experiment: it measures ice melted by the ROOM, which must be subtracted."],"mcq":[{"id":"week05.check.m1","kind":"mcq","q":"According to the caloric theory, heat is","marks":1,"level":1,"options":["a form of energy","a weightless fluid that flows from hot to cold bodies","the vibration of molecules","a type of electromagnetic radiation"],"answer":"B","explanation":"The caloric theory treated heat as an invisible, weightless fluid (caloric). A is the modern (kinetic) view — the very idea that replaced caloric.","section":"p01"},{"id":"week05.check.m2","kind":"mcq","q":"Joule's paddle-wheel experiments were important because they showed that","marks":1,"level":1,"options":["heat is a fluid","a fixed amount of work always produces the same amount of heat","water has a high specific heat capacity","temperature depends on pressure"],"answer":"B","explanation":"Joule found work and heat are equivalent (mechanical equivalent of heat), supporting conservation of energy. C is true of water but not what his experiments established.","section":"p01"},{"id":"week05.check.m3","kind":"mcq","q":"A small iron nail at 200 °C is dropped into a bucket of water at 30 °C. Net thermal energy flows","marks":1,"level":1,"options":["from the water to the nail because the water has more energy","from the nail to the water because the nail is at a higher temperature","in both directions equally","from the water to the nail because the water has a larger mass"],"answer":"B","explanation":"Direction depends only on temperature: high → low. A is the classic trap — the bucket holds more energy, but that does not decide the direction.","section":"p01"},{"id":"week05.check.m4","kind":"mcq","q":"Which of the following is NOT a thermometric property?","marks":1,"level":1,"options":["The volume of a fixed mass of liquid","The resistance of a platinum wire","The mass of a metal block","The e.m.f. of a thermocouple"],"answer":"C","explanation":"Mass does not change with temperature. A, B and D all change continuously with temperature and are used in thermometers.","section":"p01"},{"id":"week05.check.m5","kind":"mcq","q":"The purpose of the constriction in a clinical thermometer is to","marks":1,"level":1,"options":["make the thermometer more sensitive","prevent the mercury returning to the bulb before the reading is taken","magnify the mercury thread","make the thermometer respond more quickly"],"answer":"B","explanation":"The thread breaks at the constriction so the reading stays. Sensitivity (A) comes from the narrow bore and short range; magnifying (C) is the job of the curved stem.","section":"p01"},{"id":"week05.check.m6","kind":"mcq","q":"The lower fixed point on the Celsius scale is the temperature of","marks":1,"level":1,"options":["water at its maximum density","pure melting ice at standard atmospheric pressure","salt water freezing","the coldest possible temperature"],"answer":"B","explanation":"Ice point = pure melting ice at ⟪1\\,\\mathrm{atm}=0\\,{}^{\\circ}\\mathrm{C}⟫. Water's maximum density (A) is at 4 °C; the coldest possible temperature (D) is absolute zero, −273 °C.","section":"p01"},{"id":"week05.check.m7","kind":"mcq","q":"Which thermometer is MOST suitable for measuring the rapidly changing temperature inside a furnace at 1200 °C?","marks":1,"level":1,"options":["Mercury-in-glass","Alcohol-in-glass","Clinical","Thermocouple"],"answer":"D","explanation":"A thermocouple has a very wide range and a tiny junction, so it responds quickly. Mercury (A) boils at 357 °C and the glass would melt.","section":"p01"},{"id":"week05.check.m8","kind":"mcq","q":"When the temperature of a gas increases, its molecules","marks":1,"level":1,"options":["become larger","move faster on average","stop colliding","lose kinetic energy"],"answer":"B","explanation":"Temperature is related to the average kinetic energy of the molecules, so they move faster. A is a common misconception — molecules do not grow.","section":"p01"},{"id":"week05.check.m9","kind":"mcq","q":"Gases are much easier to compress than liquids because","marks":1,"level":1,"options":["gas molecules are smaller","there are large spaces between gas molecules","gas molecules move more slowly","the forces between gas molecules are stronger"],"answer":"B","explanation":"Large spaces between gas molecules can be reduced. D is the opposite of the truth — forces in a gas are very weak.","section":"p01"},{"id":"week05.check.m10","kind":"mcq","q":"A bimetallic strip bends when heated because","marks":1,"level":1,"options":["the two metals have different masses","one metal melts","the two metals expand by different amounts","heat flows from one metal to the other"],"answer":"C","explanation":"Unequal expansion forces the strip to curve, with the metal that expands more on the outside. Different masses (A) have no effect on bending.","section":"p01"},{"id":"week05.check.m11","kind":"mcq","q":"Water has its maximum density at","marks":1,"level":1,"options":["0 °C","4 °C","37 °C","100 °C"],"answer":"B","explanation":"Water contracts down to 4 °C then expands as it cools to 0 °C, so it is densest at 4 °C. 0 °C (A) is the freezing point, where ice (less dense) forms.","section":"p01"},{"id":"week05.check.m12","kind":"mcq","q":"How much energy is needed to raise the temperature of 2.0 kg of a substance of specific heat capacity 500 J kg^−1^ °C^−1^ by 10 °C?","marks":1,"level":1,"options":["1000 J","2500 J","10 000 J","100 000 J"],"answer":"C","explanation":"⟪E=mc\\Delta \\theta =2.0\\times 500\\times 10=10\\,000\\,\\mathrm{J}⟫. B comes from wrongly dividing ⟪(500\\times 10\\div 2)⟫.","section":"p01"},{"id":"week05.check.m13","kind":"mcq","q":"A block has a heat capacity of 400 J °C^−1^. How much energy raises its temperature by 5 °C?","marks":1,"level":1,"options":["80 J","400 J","2000 J","4000 J"],"answer":"C","explanation":"⟪E=C\\Delta \\theta =400\\times 5=2000\\,\\mathrm{J}⟫. ⟪A\\ (400\\div 5)⟫ divides instead of multiplying. Heat capacity already includes the mass, so do not multiply by m.","section":"p01"},{"id":"week05.check.m14","kind":"mcq","q":"A 1000 W heater supplies energy to melting ice for 68 s. All the energy melts ice. What mass of ice melts? ⟪(l_{f}=3.4\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","marks":1,"level":1,"options":["0.020 kg","0.20 kg","2.0 kg","5.0 kg"],"answer":"B","explanation":"⟪E=Pt=1000\\times 68=68\\,000\\,\\mathrm{J}⟫; ⟪m=E\\div l=68\\,000\\div 340\\,000=0.20\\,\\mathrm{kg}⟫. D comes from ⟪l\\div E⟫ upside down.","section":"p01"},{"id":"week05.check.m15","kind":"mcq","q":"Which statement about evaporation is correct?","marks":1,"level":1,"options":["It occurs only at the boiling point","It occurs throughout the liquid","It occurs at the surface at any temperature and cools the liquid","It needs bubbles to form"],"answer":"C","explanation":"Evaporation is a surface process at any temperature, and the escape of the fastest molecules cools the liquid. A, B and D describe boiling.","section":"p01"}],"structured":[{"id":"week05.check.s1","kind":"multi","title":"Thermometers","total":12,"stem":["Thermometers are designed to suit the job they do."],"stemBlocks":[],"parts":[{"id":"week05.check.s1.a","kind":"self","q":"Define (i) temperature; (ii) the upper fixed point of the Celsius scale.","marks":2,"level":2,"lines":3,"scheme":"(i) A measure of the degree of hotness of a body / related to the average KE of its molecules (1). (ii) Temperature of steam above pure water boiling at standard atmospheric pressure (100 °C) (1).","points":[{"text":"(i) A measure of the degree of hotness of a body / related to the average KE of its molecules","marks":1},{"text":"(ii) Temperature of steam above pure water boiling at standard atmospheric pressure (100 °C)","marks":1}],"label":"(a)"},{"id":"week05.check.s1.b","kind":"self","q":"Describe TWO features of a clinical thermometer and explain the purpose of each.","marks":4,"level":3,"lines":5,"scheme":"Constriction (1) — stops mercury flowing back so the reading is kept (1). Short range 35–42 °C / fine bore (1) — high sensitivity, reads to 0.1 °C (1). [Accept thin bulb → quick response; lens-shaped stem → magnifies thread.]","points":[{"text":"Constriction","marks":1},{"text":"— stops mercury flowing back so the reading is kept","marks":1},{"text":"Short range 35–42 °C / fine bore","marks":1},{"text":"— high sensitivity, reads to 0.1 °C. [Accept thin bulb → quick response; lens-shaped stem → magnifies thread.]","marks":1}],"label":"(b)"},{"id":"week05.check.s1.c","kind":"self","q":"The mercury thread of an unmarked thermometer is 3.0 cm long at the ice point and 23.0 cm long at the steam point. In a room it is 8.6 cm long. Calculate the room temperature.","marks":3,"level":2,"lines":4,"scheme":"⟪\\theta =(l-l_{0})\\div (l_{100}-l_{0})\\times 100⟫ (1) ⟪=(8.6-3.0)\\div 20.0\\times 100⟫ (1) ⟪=28\\,{}^{\\circ}\\mathrm{C}⟫ (1).","points":[{"text":"⟪\\theta =(l-l_{0})\\div (l_{100}-l_{0})\\times 100⟫","marks":1},{"text":"⟪=(8.6-3.0)\\div 20.0\\times 100⟫","marks":1},{"text":"⟪=28\\,{}^{\\circ}\\mathrm{C}⟫","marks":1}],"num":{"value":28,"sf":2,"unit":"°C","unitTex":"{}^{\\circ}\\mathrm{C}"},"label":"(c)","autoKind":"num"},{"id":"week05.check.s1.d","kind":"self","q":"Give TWO advantages of a thermocouple over a mercury-in-glass thermometer.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): wider range / can measure very high temperatures; responds faster (small junction, small heat capacity); measures temperature at a point; can be read remotely/connected to a data logger.","points":[{"text":"Any two (1 each): wider range / can measure very high temperatures; responds faster (small junction, small heat capacity); measures temperature at a point; can be read remotely/connected to a data logger.","marks":2,"each":true}],"label":"(d)"},{"id":"week05.check.s1.e","kind":"self","q":"Explain why an alcohol thermometer is used in Antarctica where temperatures fall to −60 °C.","marks":1,"level":1,"lines":2,"scheme":"Alcohol freezes at −115 °C (below −60 °C) whereas mercury freezes at −39 °C (1).","points":[{"text":"Alcohol freezes at −115 °C (below −60 °C) whereas mercury freezes at −39 °C","marks":1}],"label":"(e)"}]},{"id":"week05.check.s2","kind":"multi","title":"Specific heat capacity of a liquid","total":13,"stem":["A student finds the specific heat capacity of cooking oil. 0.20 kg of oil is placed in a copper calorimeter of mass 0.10 kg. A 12 V immersion heater carrying 2.0 A heats the oil for 5.0 minutes and its temperature rises by 15 °C. ⟪(c_{\\text{copper}}=390\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫"],"stemBlocks":[],"parts":[{"id":"week05.check.s2.a","kind":"self","q":"State how the ammeter and the voltmeter are connected to the heater.","marks":2,"level":2,"lines":2,"scheme":"Ammeter in series with the heater (1); voltmeter in parallel (across) the heater (1).","points":[{"text":"Ammeter in series with the heater","marks":1},{"text":"voltmeter in parallel (across) the heater","marks":1}],"label":"(a)"},{"id":"week05.check.s2.b","kind":"self","q":"Calculate the electrical energy supplied by the heater.","marks":2,"level":2,"lines":3,"scheme":"⟪E=VIt=12\\times 2.0\\times 300⟫ (1) ⟪=7200\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=VIt=12\\times 2.0\\times 300⟫","marks":1},{"text":"⟪=7200\\,\\mathrm{J}⟫","marks":1}],"num":{"value":7200,"sf":2,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(b)","autoKind":"num"},{"id":"week05.check.s2.c","kind":"self","q":"Calculate the heat absorbed by the copper calorimeter.","marks":2,"level":2,"lines":3,"scheme":"⟪E=mc\\Delta \\theta =0.10\\times 390\\times 15⟫ (1) ⟪=585\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta =0.10\\times 390\\times 15⟫","marks":1},{"text":"⟪=585\\,\\mathrm{J}⟫","marks":1}],"num":{"value":585,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(c)","autoKind":"num"},{"id":"week05.check.s2.d","kind":"self","q":"Hence calculate the specific heat capacity of the oil, assuming no heat is lost.","marks":3,"level":2,"lines":4,"scheme":"Heat to oil ⟪=7200-585=6615\\,\\mathrm{J}⟫ (1). ⟪c=6615\\div (0.20\\times 15)⟫ (1) ⟪=2205\\approx 2.2\\times 10^{3}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫ (1).","points":[{"text":"Heat to oil ⟪=7200-585=6615\\,\\mathrm{J}⟫","marks":1},{"text":"⟪c=6615\\div (0.20\\times 15)⟫","marks":1},{"text":"⟪=2205\\approx 2.2\\times 10^{3}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}⟫","marks":1}],"num":{"value":2200,"sf":2,"unit":"J kg^−1^ °C^−1^","unitTex":"\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1}"},"label":"(d)","autoKind":"num"},{"id":"week05.check.s2.e","kind":"self","q":"State TWO precautions the student should take to get an accurate result.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): lag/insulate the calorimeter and use a lid; stir the oil before reading the temperature; record the highest temperature reached; read thermometer at eye level; keep heater fully immersed.","points":[{"text":"Any two (1 each): lag/insulate the calorimeter and use a lid; stir the oil before reading the temperature; record the highest temperature reached; read thermometer at eye level; keep heater fully immersed.","marks":2,"each":true}],"label":"(e)"},{"id":"week05.check.s2.f","kind":"self","q":"Use your answer to (d) to explain why water is better than oil as a coolant in a car engine. ⟪(c_{\\text{water}}=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":2,"level":2,"lines":3,"scheme":"Water has about twice the specific heat capacity of oil (1), so the same mass of water absorbs more heat for the same temperature rise / takes away more heat from the engine (1).","points":[{"text":"Water has about twice the specific heat capacity of oil","marks":1},{"text":"so the same mass of water absorbs more heat for the same temperature rise / takes away more heat from the engine","marks":1}],"label":"(f)"}]},{"id":"week05.check.s3","kind":"multi","title":"Changes of state","total":13,"stem":["Ice at −20 °C is heated at a steady rate until it becomes steam. The heating curve is shown below."],"stemBlocks":[],"parts":[{"id":"week05.check.s3.a","kind":"self","q":"State the physical state(s) of the water in section B and in section D.","marks":2,"level":2,"img":{"src":"img/week05/heating_curve","alt":"State the physical state(s) of the water in section B and in section D.","w":1134,"h":694},"lines":2,"scheme":"B: solid and liquid (ice melting) (1). D: liquid and gas (water boiling) (1).","points":[{"text":"B: solid and liquid (ice melting)","marks":1},{"text":"D: liquid and gas (water boiling)","marks":1}],"label":"(a)"},{"id":"week05.check.s3.b","kind":"self","q":"Explain, in terms of molecules, why the temperature does not change in section D even though heat is supplied.","marks":2,"level":2,"lines":3,"scheme":"Energy is used to overcome the forces/break bonds between molecules (increase PE) (1), not to increase their kinetic energy, so the temperature stays constant (1).","points":[{"text":"Energy is used to overcome the forces/break bonds between molecules (increase PE)","marks":1},{"text":"not to increase their kinetic energy, so the temperature stays constant","marks":1}],"label":"(b)"},{"id":"week05.check.s3.c","kind":"self","q":"Section D is much longer than section B. What does this tell you about the specific latent heats of water?","marks":2,"level":2,"lines":3,"scheme":"More energy is needed to boil 1 kg than to melt 1 kg (1): the specific latent heat of vaporisation is (much) greater than that of fusion (1).","points":[{"text":"More energy is needed to boil 1 kg than to melt 1 kg","marks":1},{"text":": the specific latent heat of vaporisation is (much) greater than that of fusion","marks":1}],"label":"(c)"},{"id":"week05.check.s3.d","kind":"self","q":"A 500 W heater is used. Calculate the time needed to change 0.050 kg of water at 100 °C completely into steam. ⟪(l_{v}=2.26\\times 10^{6}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1})⟫","marks":3,"level":2,"lines":4,"scheme":"⟪E=ml=0.050\\times 2.26\\times 10^{6}=113\\,000\\,\\mathrm{J}⟫ (1). ⟪t=E\\div P⟫ (1) ⟪=113\\,000\\div 500=226\\,\\mathrm{s}⟫ (1).","points":[{"text":"⟪E=ml=0.050\\times 2.26\\times 10^{6}=113\\,000\\,\\mathrm{J}⟫","marks":1},{"text":"⟪t=E\\div P⟫","marks":1},{"text":"⟪=113\\,000\\div 500=226\\,\\mathrm{s}⟫","marks":1}],"num":{"value":226,"sf":3,"unit":"s","unitTex":"\\mathrm{s}"},"label":"(d)","autoKind":"num"},{"id":"week05.check.s3.e","kind":"self","q":"State TWO differences between evaporation and boiling.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): evaporation at any temperature vs boiling at a fixed temperature; surface only vs throughout; no bubbles vs bubbles; evaporation cools the liquid vs constant temperature.","points":[{"text":"Any two (1 each): evaporation at any temperature vs boiling at a fixed temperature; surface only vs throughout; no bubbles vs bubbles; evaporation cools the liquid vs constant temperature.","marks":2,"each":true}],"label":"(e)"},{"id":"week05.check.s3.f","kind":"self","q":"Explain why evaporation of sweat cools the body.","marks":2,"level":2,"lines":3,"scheme":"The most energetic (fastest) molecules escape from the surface (1), lowering the average KE of the remaining liquid; latent heat is taken from the skin, so the body cools (1).","points":[{"text":"The most energetic (fastest) molecules escape from the surface","marks":1},{"text":"lowering the average KE of the remaining liquid; latent heat is taken from the skin, so the body cools","marks":1}],"label":"(f)"}]}],"n":36},{"id":"week05.past","kind":"past","title":"Past-paper practice","titleText":"Past-paper practice","check":true,"log":true,"questions":[{"id":"week05.past.q1","kind":"multi","title":"Data analysis — cooling curve (Paper 02 Question 1 style)","total":25,"stem":["A student melted 0.050 kg of a solid wax, X, in a boiling tube. She then removed the tube from the water bath and recorded the temperature, θ, of X every minute as it cooled. Her results are shown below."],"stemBlocks":[{"type":"table","headers":["Time, t / min","0","1","2","3","4","5","6","7"],"rows":[["Temperature, θ / °C","92","84","78","73","70","70","70","70"]]},{"type":"table","headers":["Time, t / min","8","9","10","11","12","13","14"],"rows":[["Temperature, θ / °C","70","70","66","60","55","51","48"]]}],"parts":[{"id":"week05.past.q1.a","kind":"self","q":"On the grid provided, plot a graph of temperature, θ (y-axis), against time, t (x-axis). Draw a smooth curve through the points.","marks":7,"level":3,"img":{"src":"img/week05/graph_paper","alt":"On the grid provided, plot a graph of temperature, θ (y-axis), against time, t (x-axis). Draw a smooth curve through the points.","w":1174,"h":894},"lines":0,"scheme":"Axes correct way round and labelled with quantity and unit ⟪(1+1)⟫; suitable scale using more than half the grid (y-axis may start at 40 °C) (1); all points plotted correctly (2: −1 per error, max 2); smooth curve with horizontal section (1); title (1).","points":[{"text":"Axes correct way round and labelled with quantity and unit","marks":2},{"text":"suitable scale using more than half the grid (y-axis may start at 40 °C)","marks":1},{"text":"all points plotted correctly","marks":2},{"text":"smooth curve with horizontal section","marks":1},{"text":"title","marks":1}],"label":"(a)","grid":true},{"id":"week05.past.q1.b","kind":"self","q":"Use your graph to state the melting point of X.","marks":1,"level":1,"lines":1,"scheme":"70 °C (1).","points":[{"text":"70 °C","marks":1}],"num":{"value":70,"sf":1,"unit":"°C","unitTex":"{}^{\\circ}\\mathrm{C}"},"label":"(b)","autoKind":"num"},{"id":"week05.past.q1.c","kind":"self","q":"Determine from your graph how long it took X to solidify.","marks":2,"level":2,"lines":2,"scheme":"Flat section from ⟪t=4\\,\\mathrm{min}⟫ to ⟪t=9\\,\\mathrm{min}⟫ (1); about 5 minutes (accept 5–6 min) (1).","points":[{"text":"Flat section from ⟪t=4\\,\\mathrm{min}⟫ to ⟪t=9\\,\\mathrm{min}⟫","marks":1},{"text":"about 5 minutes (accept 5–6 min)","marks":1}],"label":"(c)"},{"id":"week05.past.q1.d","kind":"self","q":"State the physical state of X at (i) ⟪t=2\\,\\mathrm{min}⟫; (ii) ⟪t=7\\,\\mathrm{min}⟫.","marks":2,"level":2,"lines":2,"scheme":"(i) Liquid (1). (ii) Liquid and solid (freezing / solidifying) (1).","points":[{"text":"(i) Liquid","marks":1},{"text":"(ii) Liquid and solid (freezing / solidifying)","marks":1}],"label":"(d)"},{"id":"week05.past.q1.e","kind":"self","q":"Explain why the temperature of X remained constant between 4 and 9 minutes.","marks":3,"level":2,"lines":4,"scheme":"X was changing state (freezing) (1). As the molecules form bonds they release latent heat (of fusion) (1), which balances/replaces the heat lost to the surroundings, so there is no change in KE and the temperature stays constant (1).","points":[{"text":"X was changing state (freezing)","marks":1},{"text":"As the molecules form bonds they release latent heat (of fusion)","marks":1},{"text":"which balances/replaces the heat lost to the surroundings, so there is no change in KE and the temperature stays constant","marks":1}],"label":"(e)"},{"id":"week05.past.q1.f","kind":"self","q":"Calculate the average rate of cooling of X during the first 2 minutes. Give the unit.","marks":3,"level":2,"lines":3,"scheme":"Rate ⟪=(92-78)\\div 2⟫ (1) ⟪=7.0⟫ (1) °C min⁻¹ (1).","points":[{"text":"Rate ⟪=(92-78)\\div 2⟫","marks":1},{"text":"⟪=7.0⟫","marks":1},{"text":"°C min⁻¹","marks":1}],"label":"(f)"},{"id":"week05.past.q1.g","kind":"self","q":"Suggest why the rate of cooling between 10 and 14 minutes is smaller than during the first 2 minutes.","marks":2,"level":2,"lines":3,"scheme":"The temperature difference between X and the surroundings is smaller (1), so heat is lost more slowly (1).","points":[{"text":"The temperature difference between X and the surroundings is smaller","marks":1},{"text":"so heat is lost more slowly","marks":1}],"label":"(g)"},{"id":"week05.past.q1.h","kind":"self","q":"During solidification X lost heat to the surroundings at an average rate of 30 W. Use your answer to (c) to calculate the specific latent heat of fusion of X.","marks":3,"level":2,"lines":4,"scheme":"⟪E=Pt=30\\times 300=9000\\,\\mathrm{J}⟫ (1); ⟪l=E\\div m=9000\\div 0.050⟫ (1) ⟪=1.8\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫ (1). [Allow error carried forward from (c).]","points":[{"text":"⟪E=Pt=30\\times 300=9000\\,\\mathrm{J}⟫","marks":1},{"text":"⟪l=E\\div m=9000\\div 0.050⟫","marks":1},{"text":"⟪=1.8\\times 10^{5}\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}⟫. [Allow error carried forward from (c).]","marks":1}],"label":"(h)"},{"id":"week05.past.q1.i","kind":"self","q":"State TWO precautions the student should take in this experiment.","marks":2,"level":2,"lines":3,"scheme":"Any two (1 each): use a water bath, not a direct flame (wax is flammable); thermometer bulb fully immersed in X; read thermometer at eye level (avoid parallax); stir while liquid; take readings at exact time intervals.","points":[{"text":"Any two (1 each): use a water bath, not a direct flame (wax is flammable); thermometer bulb fully immersed in X; read thermometer at eye level (avoid parallax); stir while liquid; take readings at exact time intervals.","marks":2,"each":true}],"label":"(i)"}]},{"id":"week05.past.q2","kind":"multi","title":"Heat as energy (extended-response style)","total":15,"stem":["Ideas about the nature of heat changed greatly between 1750 and 1850. Today, many Caribbean homes use solar water heaters."],"stemBlocks":[],"parts":[{"id":"week05.past.q2.a","kind":"self","q":"Distinguish between the caloric theory and the kinetic theory of heat, and describe ONE observation made by Count Rumford that the caloric theory could not explain.","marks":4,"level":3,"lines":6,"scheme":"Caloric: heat is a weightless fluid flowing from hot to cold, fixed in amount (1). Kinetic: heat is energy of the motion of particles; it can be produced by doing work (1). Rumford: boring cannon produced heat for as long as boring continued / a blunt drill produced more heat (1), so heat was unlimited and came from work against friction, not a stored fluid (1).","points":[{"text":"Caloric: heat is a weightless fluid flowing from hot to cold, fixed in amount","marks":1},{"text":"Kinetic: heat is energy of the motion of particles; it can be produced by doing work","marks":1},{"text":"Rumford: boring cannon produced heat for as long as boring continued / a blunt drill produced more heat","marks":1},{"text":"so heat was unlimited and came from work against friction, not a stored fluid","marks":1}],"label":"(a)"},{"id":"week05.past.q2.b","kind":"self","q":"Describe Joule's paddle-wheel experiment and explain how it supported the principle of conservation of energy.","marks":4,"level":3,"lines":6,"scheme":"Falling masses turned paddles in insulated water (1). Work done = loss of PE (mgh) was calculated and the temperature rise of the water measured (1). A fixed amount of work always produced the same amount of heat (1), so mechanical energy is converted into heat with none lost — energy is conserved (1).","points":[{"text":"Falling masses turned paddles in insulated water","marks":1},{"text":"Work done = loss of PE (mgh) was calculated and the temperature rise of the water measured","marks":1},{"text":"A fixed amount of work always produced the same amount of heat","marks":1},{"text":"so mechanical energy is converted into heat with none lost — energy is conserved","marks":1}],"label":"(b)"},{"id":"week05.past.q2.c","kind":"self","q":"A solar water heater tank holds 150 kg of water. On a sunny day the water is heated from 26 °C to 56 °C. Calculate the heat energy absorbed by the water. ⟪(c=4200\\,\\mathrm{J}\\,\\mathrm{kg}^{-1}\\,{}^{\\circ}\\mathrm{C}^{-1})⟫","marks":3,"level":2,"lines":4,"scheme":"⟪E=mc\\Delta \\theta⟫ (1) ⟪=150\\times 4200\\times 30⟫ (1) ⟪=1.89\\times 10^{7}\\,\\mathrm{J}⟫ (1).","points":[{"text":"⟪E=mc\\Delta \\theta⟫","marks":1},{"text":"⟪=150\\times 4200\\times 30⟫","marks":1},{"text":"⟪=1.89\\times 10^{7}\\,\\mathrm{J}⟫","marks":1}],"num":{"value":18900000,"sf":3,"unit":"J","unitTex":"\\mathrm{J}"},"label":"(c)","autoKind":"num"},{"id":"week05.past.q2.d","kind":"self","q":"Calculate how long a 3.0 kW electric heater would take to supply the same energy. Give your answer in hours.","marks":2,"level":2,"lines":3,"scheme":"⟪t=E\\div P=1.89\\times 10^{7}\\div 3000=6300\\,\\mathrm{s}⟫ (1) ⟪=1.75\\,\\mathrm{h}⟫ (1).","points":[{"text":"⟪t=E\\div P=1.89\\times 10^{7}\\div 3000=6300\\,\\mathrm{s}⟫","marks":1},{"text":"⟪=1.75\\,\\mathrm{h}⟫","marks":1}],"label":"(d)"},{"id":"week05.past.q2.e","kind":"self","q":"Explain why water is a good substance for storing heat in the tank.","marks":2,"level":2,"lines":3,"scheme":"Water has a high specific heat capacity (1), so it absorbs/stores a lot of energy for a small temperature rise and cools down slowly (1).","points":[{"text":"Water has a high specific heat capacity","marks":1},{"text":"so it absorbs/stores a lot of energy for a small temperature rise and cools down slowly","marks":1}],"label":"(e)"}]}],"n":37}]};
